 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_job public.jobs;
  v_tpl public.form_templates;
begin
  if v_uid is null then return; end if;
  select * into v_job from public.jobs where id = p_job_id and user_id = v_uid;
  if not found then return; end if;
  select * into v_tpl from public.form_templates
  where id = p_template_id and user_id = v_uid and archived_at is null;
  if not found then return; end if;

  insert into public.job_forms (user_id, job_id, template_id, template_name, fields, source)
  values (v_uid, v_job.id, v_tpl.id, v_tpl.name,
          public.form_template_snapshot(v_tpl.id, v_uid), 'manual')
  on conflict (job_id, template_id) do nothing;

  return query select * from public.job_forms
    where job_id = v_job.id and user_id = v_uid and template_id = v_tpl.id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_actor_context(p_tenant uuid, p_customer uuid)
 RETURNS TABLE(actor_type text, actor_id uuid, actor_label text, source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_override jsonb;
  v_claims text;
  v_role text;
  v_tech record;
begin
  -- Trusted override: transaction-local GUC set by in-DB code (or a service
  -- connection) that knows better than inference â€” e.g. a future RPC recording
  -- "owner recorded customer decision". Honored only when it parses and names
  -- a legal actor_type; garbage falls through to inference.
  begin
    v_override := nullif(current_setting('app.audit_context', true), '')::jsonb;
  exception when others then
    v_override := null;
  end;
  if v_override is not null
     and v_override->>'actor_type' in ('owner', 'worker', 'customer', 'system') then
    return query select
      v_override->>'actor_type',
      nullif(v_override->>'actor_id', '')::uuid,
      nullif(v_override->>'actor_label', ''),
      case when v_override->>'source' in ('dashboard','crew','portal','service','db')
           then v_override->>'source' else 'service' end;
    return;
  end if;

  if v_uid is not null then
    -- The tenant key IS the owner's auth uid â€” equality is the ownership test.
    if v_uid = p_tenant then
      return query select 'owner'::text, v_uid, null::text, 'dashboard'::text;
      return;
    end if;
    -- Attribution deliberately ignores is_active/archived_at: authorization is
    -- the RPCs' job; attribution must still name a just-deactivated tech.
    select t.id, t.name into v_tech
      from public.technicians t
     where t.auth_user_id = v_uid and t.user_id = p_tenant
     limit 1;
    if found then
      return query select 'worker'::text, v_uid, v_tech.name, 'crew'::text;
      return;
    end if;
    -- A signed-in uid that is neither this tenant nor its worker: a privileged
    -- server path acting across tenants. Named honestly as system.
    return query select 'system'::text, v_uid, 'unrecognized session'::text, 'service'::text;
    return;
  end if;

  -- No JWT subject. PostgREST stamps request.jwt.claims for every API request
  -- (anon included); its absence means a direct database session.
  v_claims := nullif(current_setting('request.jwt.claims', true), '');
  if v_claims is null then
    return query select 'system'::text, null::uuid, null::text, 'db'::text;
    return;
  end if;
  begin
    v_role := v_claims::jsonb->>'role';
  exception when others then
    v_role := null;
  end;
  if v_role = 'anon' then
    -- The portal and public booking funnel are the only anonymous writers.
    return query select
      'customer'::text,
      p_customer,
      (select c.name from public.customers c
        where c.id = p_customer and c.user_id = p_tenant),
      'portal'::text;
    return;
  end if;
  return query select 'system'::text, null::uuid, null::text,
    case when v_role = 'service_role' then 'service' else 'db' end;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_change_orders()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_action text;
begin
  if tg_op = 'INSERT' then
    perform public.audit_log(new.user_id, 'change_order_created', 'change_order',
      new.id, new.co_number, new.customer_id,
      null,
      jsonb_build_object('status', new.status, 'amount', new.amount,
                         'description', left(new.description, 140)));
    return null;
  end if;

  if new.status is distinct from old.status then
    v_action := case new.status
      when 'pending'   then 'change_order_sent'
      when 'approved'  then 'change_order_approved'
      when 'declined'  then 'change_order_declined'
      when 'cancelled' then 'change_order_cancelled'
      else 'change_order_status_changed'
    end;
    -- decided_via is the provenance of the DECISION (portal = the customer
    -- tapped it; owner = the owner recorded a decision taken elsewhere). The
    -- event's actor is who performed the WRITE. Both are kept, neither is
    -- inferred from the other.
    perform public.audit_log(new.user_id, v_action, 'change_order', new.id,
      new.co_number, new.customer_id,
      jsonb_build_object('status', old.status),
      jsonb_build_object('status', new.status, 'amount', new.amount)
        || case when new.decided_via is not null
             then jsonb_build_object('decided_via', new.decided_via)
             else '{}'::jsonb end
        || case when new.decline_reason is not null
             then jsonb_build_object('decline_reason', new.decline_reason)
             else '{}'::jsonb end);
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_customers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_before jsonb := '{}'::jsonb;
  v_after jsonb := '{}'::jsonb;
begin
  if tg_op = 'INSERT' then
    perform public.audit_log(new.user_id, 'customer_added', 'customer', new.id,
      new.name, new.id, null,
      case when new.acquisition_source is not null
           then jsonb_build_object('source', new.acquisition_source)
           else null end);
    return null;
  end if;

  if tg_op = 'DELETE' then
    perform public.audit_log(old.user_id, 'customer_deleted', 'customer', old.id,
      old.name, old.id,
      jsonb_build_object('name', old.name), null);
    return null;
  end if;

  if new.archived_at is distinct from old.archived_at then
    perform public.audit_log(new.user_id,
      case when new.archived_at is not null then 'customer_archived' else 'customer_restored' end,
      'customer', new.id, new.name, new.id, null, null);
  end if;

  -- Contact identity: only the keys that actually changed, both sides.
  if new.name is distinct from old.name then
    v_before := v_before || jsonb_build_object('name', old.name);
    v_after  := v_after  || jsonb_build_object('name', new.name);
  end if;
  if new.email is distinct from old.email then
    v_before := v_before || jsonb_build_object('email', old.email);
    v_after  := v_after  || jsonb_build_object('email', new.email);
  end if;
  if new.phone is distinct from old.phone then
    v_before := v_before || jsonb_build_object('phone', old.phone);
    v_after  := v_after  || jsonb_build_object('phone', new.phone);
  end if;
  if v_after <> '{}'::jsonb then
    perform public.audit_log(new.user_id, 'customer_contact_updated', 'customer',
      new.id, new.name, new.id, v_before, v_after);
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_events_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  raise exception
    'audit_events is append-only: the audit trail is evidence, and evidence does not get edited. Maintenance requires deliberately disabling trigger audit_events_no_mutate as superuser.'
    using errcode = 'restrict_violation';
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_invoices()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_action text;
begin
  if tg_op = 'INSERT' then
    perform public.audit_log(new.user_id, 'invoice_created', 'invoice', new.id,
      new.invoice_number, new.customer_id,
      null,
      jsonb_build_object('status', new.status, 'amount', new.amount));
    return null;
  end if;

  if tg_op = 'DELETE' then
    perform public.audit_log(old.user_id, 'invoice_deleted', 'invoice', old.id,
      old.invoice_number, old.customer_id,
      jsonb_build_object('status', old.status, 'amount', old.amount,
                         'amount_paid', old.amount_paid),
      null);
    return null;
  end if;

  if new.status is distinct from old.status then
    v_action := case
      when new.status = 'paid'      then 'invoice_paid'
      when new.status = 'partial'   then 'invoice_partially_paid'
      when new.status = 'cancelled' then 'invoice_cancelled'
      when old.status = 'cancelled' then 'invoice_reactivated'
      when old.status = 'draft'     then 'invoice_issued'
      else 'invoice_status_changed'
    end;
    perform public.audit_log(new.user_id, v_action, 'invoice', new.id,
      new.invoice_number, new.customer_id,
      jsonb_build_object('status', old.status),
      jsonb_build_object('status', new.status, 'amount', new.amount,
                         'amount_paid', new.amount_paid));
  end if;

  if (new.amount is distinct from old.amount
      or new.discount_value is distinct from old.discount_value) then
    perform public.audit_log(new.user_id, 'invoice_edited', 'invoice', new.id,
      new.invoice_number, new.customer_id,
      jsonb_build_object('amount', old.amount, 'discount_value', old.discount_value),
      jsonb_build_object('amount', new.amount, 'discount_value', new.discount_value));
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_job_forms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_job public.jobs;
begin
  select * into v_job from public.jobs where id = new.job_id;

  if new.waived_at is not null and old.waived_at is null then
    perform public.audit_log(new.user_id, 'checklist_waived', 'visit', new.job_id,
      coalesce(v_job.title, new.template_name), v_job.customer_id,
      null,
      jsonb_build_object('form', new.template_name, 'reason', new.waive_reason),
      jsonb_build_object('form_id', new.id));
  elsif new.waived_at is null and old.waived_at is not null then
    perform public.audit_log(new.user_id, 'checklist_waive_removed', 'visit', new.job_id,
      coalesce(v_job.title, new.template_name), v_job.customer_id,
      jsonb_build_object('form', new.template_name, 'reason', old.waive_reason),
      null,
      jsonb_build_object('form_id', new.id));
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_job_recurrences()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'INSERT' then
    perform public.audit_log(new.user_id, 'plan_created', 'plan', new.id,
      null, new.customer_id,
      null,
      jsonb_build_object('freq', new.freq, 'interval_unit', new.interval_unit,
                         'interval_count', new.interval_count,
                         'start_date', new.start_date, 'end_date', new.end_date));
    return null;
  end if;

  if tg_op = 'DELETE' then
    perform public.audit_log(old.user_id, 'plan_removed', 'plan', old.id,
      null, old.customer_id,
      jsonb_build_object('freq', old.freq, 'interval_unit', old.interval_unit,
                         'interval_count', old.interval_count,
                         'start_date', old.start_date, 'end_date', old.end_date),
      null);
    return null;
  end if;

  if (new.freq is distinct from old.freq
      or new.interval_unit is distinct from old.interval_unit
      or new.interval_count is distinct from old.interval_count
      or new.end_date is distinct from old.end_date
      or new.end_count is distinct from old.end_count) then
    -- Null-valued keys are kept on purpose: "end_date: null" IS the before-
    -- state of giving a season an end.
    perform public.audit_log(new.user_id, 'plan_changed', 'plan', new.id,
      null, new.customer_id,
      jsonb_build_object('freq', old.freq, 'interval_unit', old.interval_unit,
                         'interval_count', old.interval_count,
                         'end_date', old.end_date, 'end_count', old.end_count),
      jsonb_build_object('freq', new.freq, 'interval_unit', new.interval_unit,
                         'interval_count', new.interval_count,
                         'end_date', new.end_date, 'end_count', new.end_count));
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_jobs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_action text;
  v_sessions int;
  v_lines int;
  v_photos int;
  v_old_crew text;
  v_new_crew text;
begin
  if tg_op = 'INSERT' then
    perform public.audit_log(new.user_id, 'visit_booked', 'visit', new.id,
      new.title, new.customer_id,
      null,
      jsonb_build_object('scheduled_date', new.scheduled_date,
                         'start_time', new.start_time,
                         'status', new.status)
        || case when new.recurrence_id is not null
             then jsonb_build_object('recurrence_id', new.recurrence_id)
             else '{}'::jsonb end);
    return null;
  end if;

  if tg_op = 'DELETE' then
    -- BEFORE DELETE: count what the cascade is about to take (work sessions,
    -- billable lines, photos) while they still exist. Deleting a visit is the
    -- destructive act this trail exists for â€” record the world before it.
    select count(*) into v_sessions from public.job_work_sessions s where s.job_id = old.id;
    select count(*) into v_lines    from public.job_line_items   l where l.job_id = old.id;
    select count(*) into v_photos   from public.job_photos       p where p.job_id = old.id;
    perform public.audit_log(old.user_id, 'visit_deleted', 'visit', old.id,
      old.title, old.customer_id,
      jsonb_build_object('scheduled_date', old.scheduled_date,
                         'status', old.status,
                         'price', old.price),
      null,
      jsonb_build_object('cascade', jsonb_build_object(
        'work_sessions', v_sessions, 'line_items', v_lines, 'photos', v_photos)));
    return old;
  end if;

  -- Reschedule: the date/time pair, before â†’ after.
  if (new.scheduled_date is distinct from old.scheduled_date
      or new.start_time is distinct from old.start_time) then
    perform public.audit_log(new.user_id, 'visit_rescheduled', 'visit', new.id,
      new.title, new.customer_id,
      jsonb_build_object('scheduled_date', old.scheduled_date, 'start_time', old.start_time),
      jsonb_build_object('scheduled_date', new.scheduled_date, 'start_time', new.start_time));
  end if;

  if new.status is distinct from old.status then
    v_action := case
      when new.status = 'in_progress' then 'visit_started'
      when new.status = 'completed'   then 'visit_completed'
      when new.status = 'cancelled'   then 'visit_cancelled'
      when new.status = 'scheduled'
       and old.status in ('completed', 'in_progress', 'cancelled') then 'visit_reopened'
      else 'visit_status_changed'
    end;
    perform public.audit_log(new.user_id, v_action, 'visit', new.id,
      new.title, new.customer_id,
      jsonb_build_object('status', old.status),
      jsonb_build_object('status', new.status));
  elsif new.started_at is distinct from old.started_at then
    -- Same status, clock changed: `in_progress` + started_at NULL is the
    -- established stopped-for-the-day state (work-sessions contract, no new
    -- status). Started â†’ cleared = paused; cleared â†’ started = resumed.
    if old.started_at is not null and new.started_at is null then
      perform public.audit_log(new.user_id, 'work_paused', 'visit', new.id,
        new.title, new.customer_id, null, null);
    elsif old.started_at is null and new.started_at is not null then
      perform public.audit_log(new.user_id, 'work_resumed', 'visit', new.id,
        new.title, new.customer_id, null, null);
    end if;
  end if;

  if new.crew_id is distinct from old.crew_id then
    select c.name into v_old_crew from public.crews c where c.id = old.crew_id;
    select c.name into v_new_crew from public.crews c where c.id = new.crew_id;
    perform public.audit_log(new.user_id, 'visit_crew_changed', 'visit', new.id,
      new.title, new.customer_id,
      jsonb_build_object('crew', v_old_crew),
      jsonb_build_object('crew', v_new_crew));
  end if;

  if new.price is distinct from old.price then
    perform public.audit_log(new.user_id, 'visit_price_changed', 'visit', new.id,
      new.title, new.customer_id,
      jsonb_build_object('price', old.price),
      jsonb_build_object('price', new.price));
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_log(p_tenant uuid, p_action text, p_entity_type text, p_entity_id uuid, p_entity_label text, p_customer uuid, p_before jsonb, p_after jsonb, p_meta jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor record;
begin
  select * into v_actor from public.audit_actor_context(p_tenant, p_customer);
  insert into public.audit_events
    (user_id, actor_type, actor_id, actor_label, action,
     entity_type, entity_id, entity_label, customer_id, source,
     before, after, meta)
  values
    (p_tenant, v_actor.actor_type, v_actor.actor_id, v_actor.actor_label, p_action,
     p_entity_type, p_entity_id, p_entity_label, p_customer, v_actor.source,
     p_before, p_after, p_meta);
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_payments()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_action text;
begin
  if tg_op = 'INSERT' then
    v_action := case
      when new.provider = 'refund' or new.amount < 0 then 'refund_recorded'
      when new.kind = 'credit' then 'credit_recorded'
      else 'payment_recorded'
    end;
    perform public.audit_log(new.user_id, v_action, 'payment', new.id,
      null, new.customer_id,
      null,
      jsonb_build_object('amount', new.amount, 'kind', new.kind,
                         'method', new.method, 'provider', new.provider,
                         'status', new.status),
      case when new.invoice_id is not null
           then jsonb_build_object('invoice_id', new.invoice_id)
           else null end);
    return null;
  end if;

  if tg_op = 'DELETE' then
    perform public.audit_log(old.user_id, 'payment_removed', 'payment', old.id,
      null, old.customer_id,
      jsonb_build_object('amount', old.amount, 'kind', old.kind,
                         'method', old.method, 'provider', old.provider),
      null,
      case when old.invoice_id is not null
           then jsonb_build_object('invoice_id', old.invoice_id)
           else null end);
    return null;
  end if;

  if new.status is distinct from old.status then
    perform public.audit_log(new.user_id, 'payment_status_changed', 'payment', new.id,
      null, new.customer_id,
      jsonb_build_object('status', old.status),
      jsonb_build_object('status', new.status, 'amount', new.amount));
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_quotes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_action text;
begin
  if tg_op = 'INSERT' then
    perform public.audit_log(new.user_id, 'quote_created', 'quote', new.id,
      new.quote_number, new.customer_id,
      null,
      jsonb_build_object('status', new.status, 'total', new.total));
    return null;
  end if;

  if tg_op = 'DELETE' then
    perform public.audit_log(old.user_id, 'quote_deleted', 'quote', old.id,
      old.quote_number, old.customer_id,
      jsonb_build_object('status', old.status, 'total', old.total),
      null);
    return null;
  end if;

  if new.status is distinct from old.status then
    v_action := case new.status
      when 'sent'      then 'quote_sent'
      when 'accepted'  then 'quote_accepted'
      when 'declined'  then 'quote_declined'
      when 'scheduled' then 'quote_scheduled'
      when 'completed' then 'quote_completed'
      when 'paid'      then 'quote_paid'
      else 'quote_status_changed'
    end;
    perform public.audit_log(new.user_id, v_action, 'quote', new.id,
      new.quote_number, new.customer_id,
      jsonb_build_object('status', old.status),
      jsonb_build_object('status', new.status)
        || case when new.status = 'accepted' then
             jsonb_build_object('accepted_price', new.accepted_price,
                                'selected_cadence', new.selected_cadence)
           else '{}'::jsonb end);
  end if;

  -- Price edits. `total` is GENERATED from initial_price + travel_fee â€” the
  -- one money path â€” so before/after quote the generated figure, not the parts.
  if (new.initial_price is distinct from old.initial_price
      or new.travel_fee is distinct from old.travel_fee) then
    perform public.audit_log(new.user_id, 'quote_price_changed', 'quote', new.id,
      new.quote_number, new.customer_id,
      jsonb_build_object('total', old.total),
      jsonb_build_object('total', new.total));
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_service_requests()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'INSERT' then
    perform public.audit_log(new.user_id, 'request_received', 'request', new.id,
      new.kind, new.customer_id,
      null,
      jsonb_build_object('kind', new.kind, 'from_portal', new.from_portal)
        || case when new.preferred_date is not null
             then jsonb_build_object('preferred_date', new.preferred_date)
             else '{}'::jsonb end);
    return null;
  end if;

  if old.resolved_at is null and new.resolved_at is not null then
    perform public.audit_log(new.user_id, 'request_resolved', 'request', new.id,
      new.kind, new.customer_id, null, null);
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_technicians()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_old_crew text;
  v_new_crew text;
begin
  if tg_op = 'INSERT' then
    perform public.audit_log(new.user_id, 'worker_added', 'worker', new.id,
      new.name, null, null,
      jsonb_build_object('role', new.role, 'is_active', new.is_active));
    return null;
  end if;

  if tg_op = 'DELETE' then
    perform public.audit_log(old.user_id, 'worker_removed', 'worker', old.id,
      old.name, null,
      jsonb_build_object('role', old.role, 'is_active', old.is_active),
      null);
    return null;
  end if;

  if new.is_active is distinct from old.is_active then
    perform public.audit_log(new.user_id,
      case when new.is_active then 'worker_access_enabled' else 'worker_access_disabled' end,
      'worker', new.id, new.name, null,
      jsonb_build_object('is_active', old.is_active),
      jsonb_build_object('is_active', new.is_active));
  end if;

  if new.archived_at is distinct from old.archived_at then
    perform public.audit_log(new.user_id,
      case when new.archived_at is not null then 'worker_archived' else 'worker_restored' end,
      'worker', new.id, new.name, null, null, null);
  end if;

  if new.crew_id is distinct from old.crew_id then
    select c.name into v_old_crew from public.crews c where c.id = old.crew_id;
    select c.name into v_new_crew from public.crews c where c.id = new.crew_id;
    perform public.audit_log(new.user_id, 'worker_crew_changed', 'worker', new.id,
      new.name, null,
      jsonb_build_object('crew', v_old_crew),
      jsonb_build_object('crew', v_new_crew));
  end if;

  if new.auth_user_id is distinct from old.auth_user_id then
    perform public.audit_log(new.user_id,
      case when new.auth_user_id is not null then 'worker_account_linked' else 'worker_account_unlinked' end,
      'worker', new.id, new.name, null, null, null);
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_work_sessions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_job record;
begin
  -- 'carried' sessions are bookkeeping (a legacy total carried forward by the
  -- migration trigger), not an act anyone performed today. Not an event.
  if tg_op = 'INSERT' and new.source = 'carried' then
    return null;
  end if;

  select j.title, j.customer_id into v_job
    from public.jobs j where j.id = coalesce(new.job_id, old.job_id);

  if tg_op = 'INSERT' then
    perform public.audit_log(new.user_id, 'work_recorded', 'visit', new.job_id,
      v_job.title, v_job.customer_id,
      null,
      jsonb_build_object('worked_on', new.worked_on, 'minutes', new.minutes,
                         'workers', new.workers, 'entry', new.source),
      jsonb_build_object('session_id', new.id));
    return null;
  end if;

  if tg_op = 'DELETE' then
    perform public.audit_log(old.user_id, 'work_removed', 'visit', old.job_id,
      v_job.title, v_job.customer_id,
      jsonb_build_object('worked_on', old.worked_on, 'minutes', old.minutes,
                         'workers', old.workers),
      null,
      jsonb_build_object('session_id', old.id));
    return null;
  end if;

  if (new.minutes is distinct from old.minutes
      or new.workers is distinct from old.workers
      or new.worked_on is distinct from old.worked_on) then
    perform public.audit_log(new.user_id, 'work_edited', 'visit', new.job_id,
      v_job.title, v_job.customer_id,
      jsonb_build_object('worked_on', old.worked_on, 'minutes', old.minutes,
                         'workers', old.workers),
      jsonb_build_object('worked_on', new.worked_on, 'minutes', new.minutes,
                         'workers', new.workers),
      jsonb_build_object('session_id', new.id));
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.authenticate_api_key(p_hash text)
 RETURNS TABLE(key_id uuid, key_user_id uuid, key_name text, key_scopes text[], rate_limited boolean)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.api_keys k set
    last_used_at    = now(),
    usage_count     = k.usage_count + 1,
    rl_count        = case when k.rl_window_start is null or k.rl_window_start < now() - interval '1 minute'
                           then 1 else k.rl_count + 1 end,
    rl_window_start = case when k.rl_window_start is null or k.rl_window_start < now() - interval '1 minute'
                           then now() else k.rl_window_start end
  where k.key_hash = p_hash and k.revoked_at is null
  returning k.id, k.user_id, k.name, k.scopes, (k.rl_count > 120);
$function$;

CREATE OR REPLACE FUNCTION public.bank_job_clock_session()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_has_sessions boolean;
  v_closing      boolean;
  v_minutes      integer;
  v_sum          integer;
begin
  select exists (select 1 from public.job_work_sessions where job_id = new.id)
    into v_has_sessions;

  v_closing := old.started_at is not null
               and (
                 (new.status = 'completed' and old.status is distinct from 'completed')
                 or new.started_at is null
               );

  if v_closing then
    v_minutes := greatest(1, least(1440,
      (extract(epoch from (now() - old.started_at)) / 60)::integer));
    insert into public.job_work_sessions
      (user_id, job_id, worked_on, started_at, ended_at, minutes, workers, source)
    values
      (old.user_id, old.id, old.scheduled_date,
       old.started_at, now(), v_minutes,
       greatest(1, coalesce(new.crew_size, old.crew_size, 1)), 'clock')
    on conflict (job_id, started_at) where started_at is not null
    do update set
      ended_at = excluded.ended_at,
      minutes  = greatest(public.job_work_sessions.minutes, excluded.minutes);
    v_has_sessions := true;
    new.started_at := null;
  end if;

  if v_has_sessions then
    v_sum := public.job_session_minutes(new.id);
    if new.actual_minutes is distinct from v_sum then
      new.actual_minutes := v_sum;
    end if;
  end if;

  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.book_service(p_token text, p_payload jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid; v_customer uuid; v_prop uuid; v_returning boolean := false;
  v_name text; v_email text; v_phone text; v_digits text;
  v_address text; v_city text; v_postal text; v_province text;
  v_service text; v_sqft numeric; v_date date; v_notes text;
  v_rate numeric; v_job uuid; v_quote uuid; v_num int; v_qnum text := null; v_mode text;
begin
  select user_id into v_user from public.business_settings where booking_token = p_token and booking_enabled = true;
  if v_user is null then return null; end if;
  if (select count(*) from public.service_requests where user_id = v_user and created_at > now() - interval '1 hour') >= 30 then
    return json_build_object('error','rate_limited'); end if;

  v_name    := nullif(trim(coalesce(p_payload->>'name', p_payload->>'fullName', concat_ws(' ', p_payload->>'firstName', p_payload->>'lastName'))), '');
  v_email   := lower(nullif(trim(coalesce(p_payload->>'email','')), ''));
  v_phone   := nullif(trim(coalesce(p_payload->>'phone','')), '');
  v_address := nullif(trim(coalesce(p_payload->>'address', p_payload->>'serviceAddress','')), '');
  v_city    := nullif(trim(coalesce(p_payload->>'city','')), '');
  v_postal  := nullif(trim(coalesce(p_payload->>'postalCode', p_payload->>'postal_code','')), '');
  v_province := coalesce(nullif(trim(p_payload->>'province',''),''), 'AB');
  v_service := nullif(trim(coalesce(p_payload->>'serviceType', p_payload->>'service', p_payload->>'requestedServices','')), '');
  v_notes   := nullif(trim(coalesce(p_payload->>'notes', p_payload->>'message','')), '');
  begin v_sqft := nullif((p_payload->>'sqft')::numeric, 0); exception when others then v_sqft := null; end;
  begin v_date := (p_payload->>'requestedDate')::date; exception when others then v_date := null; end;
  if v_name is null then return json_build_object('error','missing_name'); end if;

  v_digits := right(regexp_replace(coalesce(v_phone,''),'\D','','g'),10);
  if length(v_digits)=10 then select id into v_customer from public.customers where user_id=v_user and phone is not null and right(regexp_replace(phone,'\D','','g'),10)=v_digits order by created_at desc limit 1; end if;
  if v_customer is null and v_email is not null then select id into v_customer from public.customers where user_id=v_user and lower(coalesce(email,''))=v_email order by created_at desc limit 1; end if;
  if v_customer is null and v_address is not null then select id into v_customer from public.customers where user_id=v_user and lower(coalesce(address,''))=lower(v_address) order by created_at desc limit 1; end if;

  if v_customer is not null then
    v_returning := true;
    update public.customers set phone=coalesce(phone,v_phone), email=coalesce(email,v_email) where id=v_customer;
  else
    insert into public.customers (user_id, name, email, phone, address, city, province, postal_code, acquisition_source)
      values (v_user, left(v_name,200), v_email, v_phone, v_address, v_city, v_province, v_postal, 'Online Booking') returning id into v_customer;
  end if;

  if v_address is not null then
    select id into v_prop from public.properties where customer_id=v_customer and lower(coalesce(address,''))=lower(v_address) limit 1;
    if v_prop is null then
      insert into public.properties (user_id, customer_id, address, city, province, postal_code, lawn_sqft, is_primary)
        values (v_user, v_customer, v_address, v_city, v_province, v_postal, v_sqft, not exists(select 1 from public.properties where customer_id=v_customer)) returning id into v_prop;
    end if;
  end if;

  if v_service is not null then select default_rate into v_rate from public.service_templates where user_id=v_user and lower(name)=lower(v_service) and is_active=true order by sort_order limit 1; end if;

  if v_date is not null and v_date >= current_date and v_service is not null then
    v_mode := 'booked';
    insert into public.jobs (user_id, customer_id, property_id, title, service_type, scheduled_date, status, price, notes, is_initial_visit)
      values (v_user, v_customer, v_prop, left(v_service,120), v_service, v_date, 'scheduled', v_rate, v_notes, not v_returning) returning id into v_job;
  else
    v_mode := 'quote';
    select coalesce(max((regexp_match(quote_number,'([0-9]+)$'))[1]::int),0)+1 into v_num from public.quotes where user_id=v_user and quote_number like 'EPS-'||extract(year from now())::text||'-%';
    v_qnum := 'EPS-'||extract(year from now())::text||'-'||lpad(v_num::text,4,'0');
    -- ADR-002: price_source='template_rate' and NO config version, because that is the
    -- truth — this price came from service_templates.default_rate and the pricing
    -- config never touched it. resolveQuoteProvenance() reads this as
    -- 'not_engine_priced' and says so, instead of implying a rate card it never used.
    insert into public.quotes (user_id, quote_number, customer_id, customer_name, address, service_type, initial_price, status, measured_sqft, property_id, sent_at, price_source)
      values (v_user, v_qnum, v_customer, left(v_name,200), v_address, coalesce(v_service,'Lawn Mowing'), v_rate, 'sent', v_sqft, v_prop, now(), 'template_rate') returning id into v_quote;
  end if;

  insert into public.service_requests (user_id, customer_id, message)
    values (v_user, v_customer, case when v_mode='booked'
      then 'New online booking — '||left(v_name,80)||' · '||coalesce(v_service,'service')||' on '||to_char(v_date,'Mon DD')||coalesce(' · '||v_address,'')
      else 'New quote request — '||left(v_name,80)||coalesce(' · '||v_service,'')||coalesce(' · '||v_address,'') end);

  return json_build_object('ok',true,'mode',v_mode,'returning',v_returning,'customer_id',v_customer,'job_id',v_job,'quote_id',v_quote,'quote_number',v_qnum);
end; $function$;

CREATE OR REPLACE FUNCTION public.booking_set_consent(p_token text, p_quote_id uuid, p_sms_opt_in boolean, p_email_opt_in boolean, p_prefs jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user uuid; v_customer uuid; v_old_sms boolean; v_old_email boolean;
begin
  select user_id into v_user from public.business_settings
   where booking_token = p_token and booking_enabled = true;
  if v_user is null then return false; end if;
  select customer_id into v_customer from public.quotes where id = p_quote_id and user_id = v_user;
  if v_customer is null then return false; end if;
  select sms_opt_in, email_opt_in into v_old_sms, v_old_email from public.customers where id = v_customer;
  update public.customers
     set sms_opt_in = p_sms_opt_in, email_opt_in = p_email_opt_in,
         message_prefs = coalesce(p_prefs, message_prefs)
   where id = v_customer and user_id = v_user;
  if v_old_sms is distinct from p_sms_opt_in then
    insert into public.consent_changes (user_id, customer_id, channel, old_value, new_value, source, changed_by)
    values (v_user, v_customer, 'sms', v_old_sms, p_sms_opt_in, 'portal', 'customer (website booking)');
  end if;
  if v_old_email is distinct from p_email_opt_in then
    insert into public.consent_changes (user_id, customer_id, channel, old_value, new_value, source, changed_by)
    values (v_user, v_customer, 'email', v_old_email, p_email_opt_in, 'portal', 'customer (website booking)');
  end if;
  return true;
end $function$;

CREATE OR REPLACE FUNCTION public.bump_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.conversations set
    last_message_at = new.created_at,
    last_preview    = left(new.body, 140),
    last_direction  = new.direction,
    last_channel    = new.channel,
    unread          = case when new.direction = 'inbound' then unread + 1 else unread end,
    archived_at     = case when new.direction in ('inbound','outbound') then null else archived_at end,
    snoozed_until   = case when new.direction = 'inbound' then null else snoozed_until end
  where id = new.conversation_id;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.can_provision_business()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.current_app_role() = 'owner'
      or exists (select 1 from public.beta_invites i where i.redeemed_by = auth.uid())
$function$;

CREATE OR REPLACE FUNCTION public.capture_integration_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event text; v_entity text; v_id uuid; v_user uuid; v_payload jsonb;
begin
  if tg_table_name = 'customers' then
    v_entity := 'customer'; v_id := new.id; v_user := new.user_id;
    if tg_op = 'INSERT' then
      v_event := 'customer.created';
      v_payload := jsonb_build_object('id', new.id, 'name', new.name, 'email', new.email,
        'phone', new.phone, 'address', new.address, 'city', new.city,
        'acquisition_source', new.acquisition_source, 'created_at', new.created_at);
    end if;
  elsif tg_table_name = 'quotes' then
    v_entity := 'quote'; v_id := new.id; v_user := new.user_id;
    v_payload := jsonb_build_object('id', new.id, 'quote_number', new.quote_number,
      'customer_id', new.customer_id, 'customer_name', new.customer_name,
      'property_id', new.property_id,
      'service_type', new.service_type, 'status', new.status, 'total', new.total,
      'address', new.address, 'created_at', new.created_at);
    if tg_op = 'INSERT' then
      v_event := 'quote.created';
    elsif tg_op = 'UPDATE' and new.status is distinct from old.status then
      if new.status = 'accepted' then v_event := 'quote.accepted';
      elsif new.status = 'declined' then v_event := 'quote.declined';
      end if;
    end if;
  elsif tg_table_name = 'jobs' then
    v_entity := 'job'; v_id := new.id; v_user := new.user_id;
    v_payload := jsonb_build_object('id', new.id, 'customer_id', new.customer_id,
      'property_id', new.property_id,
      'title', new.title, 'service_type', new.service_type, 'status', new.status,
      'scheduled_date', new.scheduled_date, 'price', new.price, 'crew_id', new.crew_id,
      'created_at', new.created_at);
    if tg_op = 'INSERT' then
      v_event := 'job.created';
    elsif tg_op = 'UPDATE' and new.status = 'completed' and old.status is distinct from 'completed' then
      v_event := 'job.completed';
      v_payload := v_payload || jsonb_build_object('completed_at', new.completed_at, 'actual_minutes', new.actual_minutes);
    end if;
  elsif tg_table_name = 'invoices' then
    v_entity := 'invoice'; v_id := new.id; v_user := new.user_id;
    v_payload := jsonb_build_object('id', new.id, 'invoice_number', new.invoice_number,
      'customer_id', new.customer_id, 'customer_name', new.customer_name,
      'property_id', new.property_id,
      'status', new.status, 'amount', new.amount, 'amount_paid', new.amount_paid,
      'due_date', new.due_date, 'created_at', new.created_at);
    if tg_op = 'INSERT' then
      v_event := 'invoice.created';
    elsif tg_op = 'UPDATE'
      and new.status in ('paid', 'overpaid')
      and coalesce(old.status, '') not in ('paid', 'overpaid') then
      v_event := 'invoice.paid';
      v_payload := v_payload || jsonb_build_object('paid_at', new.paid_at);
    end if;
  elsif tg_table_name = 'payments' then
    v_entity := 'payment'; v_id := new.id; v_user := new.user_id;
    if tg_op = 'INSERT'
      and coalesce(new.status, 'paid') in ('paid', 'succeeded')
      and coalesce(new.kind, 'payment') = 'payment' then
      v_event := 'payment.recorded';
      v_payload := jsonb_build_object('id', new.id, 'customer_id', new.customer_id,
        'invoice_id', new.invoice_id, 'amount', new.amount, 'currency', new.currency,
        'method', new.method, 'kind', new.kind, 'paid_at', new.paid_at, 'created_at', new.created_at);
    end if;
  elsif tg_table_name = 'service_requests' then
    v_entity := 'request'; v_id := new.id; v_user := new.user_id;
    if tg_op = 'INSERT' then
      v_event := 'request.created';
      v_payload := jsonb_build_object('id', new.id, 'customer_id', new.customer_id,
        'kind', coalesce(new.kind, 'service'),
        'message', new.message, 'status', new.status, 'created_at', new.created_at);
    end if;
  end if;

  if v_event is null or v_user is null then return new; end if;

  if not exists (select 1 from public.webhook_endpoints e where e.user_id = v_user and e.active)
     and not exists (select 1 from public.api_keys k where k.user_id = v_user and k.revoked_at is null)
  then return new; end if;

  begin
    insert into public.integration_events (user_id, event, entity_type, entity_id, payload)
    values (v_user, v_event, v_entity, v_id, v_payload);
  exception when others then
    null;
  end;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.capture_labor_observation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_sqft numeric; v_overgrowth numeric; v_freq text;
begin
  if new.actual_minutes is not null and new.actual_minutes > 0
     and (old.actual_minutes is distinct from new.actual_minutes) then
    select p.lawn_sqft into v_sqft from public.properties p where p.id = new.property_id;
    select q.overgrowth_multiplier into v_overgrowth from public.quotes q where q.id = new.quote_id;
    select r.freq into v_freq from public.job_recurrences r where r.id = new.recurrence_id;
    insert into public.labor_observations
      (user_id, job_id, property_id, service_date, sqft, service_type, crew_size, frequency, is_initial_visit, overgrowth, estimated_minutes, actual_minutes)
    values
      (new.user_id, new.id, new.property_id, new.scheduled_date, v_sqft, new.service_type, coalesce(new.crew_size,1), v_freq, coalesce(new.is_initial_visit,false), v_overgrowth, new.duration_minutes, new.actual_minutes)
    on conflict (user_id, job_id) do update set
      actual_minutes = excluded.actual_minutes, estimated_minutes = excluded.estimated_minutes,
      sqft = excluded.sqft, crew_size = excluded.crew_size, overgrowth = excluded.overgrowth,
      frequency = excluded.frequency, is_initial_visit = excluded.is_initial_visit,
      service_date = excluded.service_date, created_at = now();
  end if;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.carry_forward_job_actual_minutes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_prior integer;
  v_crew  integer;
  v_day   date;
begin
  -- 'carried' is the row this function itself writes — without this it recurses.
  if new.source = 'carried' then
    return new;
  end if;
  if exists (select 1 from public.job_work_sessions where job_id = new.job_id) then
    return new;
  end if;
  select j.actual_minutes, greatest(1, coalesce(j.crew_size, 1)), j.scheduled_date
    into v_prior, v_crew, v_day
    from public.jobs j where j.id = new.job_id;
  if coalesce(v_prior, 0) > 0 then
    insert into public.job_work_sessions
      (user_id, job_id, worked_on, minutes, workers, source)
    values (new.user_id, new.job_id, v_day, least(10080, v_prior), v_crew, 'carried');
  end if;
  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.change_order_apply_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'approved' and old.status is distinct from 'approved' then
    insert into public.job_line_items
      (user_id, job_id, description, amount, service_key, service_category, recurring, change_order_id)
    values
      (new.user_id, new.job_id, new.description, new.amount,
       coalesce(new.service_key, 'change_order'), new.service_category, false, new.id)
    on conflict (change_order_id) where change_order_id is not null do nothing;
  end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.change_order_assign_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_next int;
begin
  if new.co_number is not null and btrim(new.co_number) <> '' then return new; end if;
  select coalesce(max((regexp_replace(co_number, '\D', '', 'g'))::int), 0) + 1
    into v_next
    from public.change_orders
   where user_id = new.user_id and co_number ~ '\d';
  new.co_number := 'CO-' || lpad(v_next::text, 4, '0');
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.change_order_guard_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- A DECIDED change order is a record of what was asked and what was answered.
  -- Nothing about it may move again -- including decided_via, which is the
  -- difference between "the customer tapped approve" and "the business says they
  -- agreed". Without this an owner-recorded approval could be silently rewritten
  -- as the customer's own, which is the one claim this whole feature exists to
  -- keep honest. An exact no-op update is allowed; anything else is refused.
  if old.status in ('approved', 'declined', 'cancelled') then
    if new is distinct from old then
      raise exception 'a % change order is a record of what was answered and cannot be edited', old.status
        using errcode = '42501';
    end if;
    return new;
  end if;

  if new.job_id is distinct from old.job_id
     or new.user_id is distinct from old.user_id
     or new.customer_id is distinct from old.customer_id then
    raise exception 'a change order cannot be moved to another job, customer or business'
      using errcode = 'check_violation';
  end if;

  if new.status is distinct from old.status then
    if not (
         (old.status = 'draft'   and new.status in ('pending', 'cancelled'))
      or (old.status = 'pending' and new.status in ('approved', 'declined', 'cancelled'))
    ) then
      raise exception 'a % change order cannot become %', old.status, new.status
        using errcode = 'check_violation';
    end if;
    if new.status = 'pending'   then new.sent_at      := coalesce(old.sent_at, now()); end if;
    if new.status = 'approved'  then new.approved_at  := now(); end if;
    if new.status = 'declined'  then new.declined_at  := now(); end if;
    if new.status = 'cancelled' then new.cancelled_at := now(); end if;
  end if;

  if old.status <> 'draft'
     and (new.amount is distinct from old.amount or new.description is distinct from old.description) then
    raise exception 'the scope and price of a change order are fixed once it is sent for approval'
      using errcode = 'check_violation';
  end if;

  new.updated_at := now();
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.claim_beta_invite()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid       uuid := auth.uid();
  v_confirmed timestamptz;
  v_inv       public.beta_invites%rowtype;
begin
  if v_uid is null then
    return 'not-signed-in';
  end if;

  select u.email_confirmed_at into v_confirmed from auth.users u where u.id = v_uid;
  if v_confirmed is null then
    return 'email-unverified';
  end if;

  select * into v_inv
    from public.beta_invites i
   where i.reserved_by = v_uid or i.redeemed_by = v_uid
   order by (i.redeemed_by = v_uid) desc
   limit 1
     for update;

  if not found then
    return case when public.current_app_role() = 'owner' then 'already-owner' else 'no-invite' end;
  end if;

  if v_inv.redeemed_by = v_uid then
    return 'already-claimed';
  end if;

  if v_inv.revoked_at is not null then
    return 'revoked';
  end if;

  update public.beta_invites
     set redeemed_by = v_uid, redeemed_at = now()
   where id = v_inv.id;

  return 'claimed';
end
$function$;

CREATE OR REPLACE FUNCTION public.claim_webhook_deliveries(p_limit integer DEFAULT 25, p_user uuid DEFAULT NULL::uuid)
 RETURNS SETOF webhook_deliveries
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.webhook_deliveries d
  set status = 'processing', attempts = d.attempts + 1, last_attempt_at = now()
  where d.id in (
    select id from public.webhook_deliveries
    where status = 'pending' and next_attempt_at <= now()
      and (p_user is null or user_id = p_user)
    order by next_attempt_at
    limit greatest(1, least(coalesce(p_limit, 25), 50))
    for update skip locked
  )
  returning d.*;
$function$;

CREATE OR REPLACE FUNCTION public.clear_crew_lead_on_departure()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  update public.crews c
     set lead_technician_id = null
   where c.user_id = new.user_id
     and c.lead_technician_id = new.id
     and (c.id is distinct from new.crew_id
          or not new.is_active
          or new.archived_at is not null);
  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.clear_route_order_on_move()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.scheduled_date is distinct from old.scheduled_date
     and new.route_order is not distinct from old.route_order then
    new.route_order := null;
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.comms_insights(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select jsonb_build_object(
    'sends', (select count(*) from public.notification_log
              where user_id = auth.uid() and created_at > now() - make_interval(days => p_days)
                and status in ('sent','delivered','opened','clicked')),
    'delivered', (select count(*) from public.notification_log
                  where user_id = auth.uid() and created_at > now() - make_interval(days => p_days)
                    and status in ('delivered','opened','clicked')),
    'failed', (select count(*) from public.notification_log
               where user_id = auth.uid() and created_at > now() - make_interval(days => p_days)
                 and status in ('error','failed','bounced','spam')),
    'skipped', (select count(*) from public.notification_log
                where user_id = auth.uid() and created_at > now() - make_interval(days => p_days)
                  and status in ('skipped','disabled')),
    'inbound', (select count(*) from public.messages
                where user_id = auth.uid() and direction = 'inbound'
                  and created_at > now() - make_interval(days => p_days)),
    'needs_reply', (select count(*) from public.conversations
                    where user_id = auth.uid() and archived_at is null and last_direction = 'inbound'),
    'scheduled_pending', (select count(*) from public.scheduled_messages
                          where user_id = auth.uid() and status = 'pending'),
    'median_reply_minutes', (
      with pairs as (
        select m.created_at as in_at,
               (select min(o.created_at) from public.messages o
                 where o.user_id = m.user_id and o.customer_id = m.customer_id
                   and o.direction = 'outbound' and o.created_at > m.created_at) as out_at
        from public.messages m
        where m.user_id = auth.uid() and m.direction = 'inbound'
          and m.created_at > now() - make_interval(days => p_days)
      )
      select round((percentile_cont(0.5) within group (order by extract(epoch from (out_at - in_at)) / 60))::numeric, 1)
      from pairs
      where out_at is not null and out_at - in_at < interval '7 days'
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.create_beta_invite(p_token_hash text, p_label text, p_email text DEFAULT NULL::text, p_days integer DEFAULT 14)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id  uuid;
  v_exp timestamptz;
begin
  if auth.uid() is null
     or not exists (select 1 from public.platform_operators o where o.user_id = auth.uid()) then
    raise exception 'only a platform operator can issue beta invites' using errcode = '42501';
  end if;
  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'token_hash must be sha256 hex — never send the raw token' using errcode = '22023';
  end if;
  if p_label is null or btrim(p_label) = '' then
    raise exception 'label is required — an invite must say who it is for' using errcode = '22023';
  end if;

  v_exp := now() + make_interval(days => greatest(1, least(90, coalesce(p_days, 14))));

  insert into public.beta_invites (token_hash, label, email, created_by, expires_at)
  values (p_token_hash, btrim(p_label), nullif(lower(btrim(coalesce(p_email, ''))), ''), auth.uid(), v_exp)
  returning id into v_id;

  return jsonb_build_object('id', v_id, 'expires_at', v_exp);
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_access_states()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(
    jsonb_object_agg(
      t.id::text,
      jsonb_build_object(
        'linked', t.auth_user_id is not null,
        'email', u.email,
        'last_sign_in_at', u.last_sign_in_at,
        'invite_sent_at', t.invite_sent_at,
        'has_code', t.invite_code is not null and coalesce(t.invite_expires_at, now()) > now()
      )
    ),
    '{}'::jsonb
  )
  from public.technicians t
  left join auth.users u on u.id = t.auth_user_id
  where t.user_id = auth.uid()
    and exists (select 1 from public.business_settings b where b.user_id = auth.uid())
$function$;

CREATE OR REPLACE FUNCTION public.crew_assignment_covers(j_crew uuid, j_technician uuid, v_crew uuid, v_tech uuid)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(j_crew = v_crew, false)
      or coalesce(j_technician = v_tech, false)
$function$;

CREATE OR REPLACE FUNCTION public.crew_cancel_time_off(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_tech     uuid := public.crew_technician_id();
  v_gone     uuid;
begin
  if v_employer is null or v_tech is null then
    raise exception 'you are not on an active crew' using errcode = '42501';
  end if;
  delete from public.pto_entries p
   where p.id = p_id and p.technician_id = v_tech and p.user_id = v_employer
     and p.status = 'requested'
  returning p.id into v_gone;
  if v_gone is null then
    return jsonb_build_object('ok', false, 'reason', 'not_pending');
  end if;
  return jsonb_build_object('ok', true);
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_crew_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select t.crew_id from public.technicians t
  where t.auth_user_id = auth.uid() and t.is_active and t.archived_at is null limit 1
$function$;

CREATE OR REPLACE FUNCTION public.crew_day(p_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_crew     uuid := public.crew_crew_id();
  v_tech     uuid := public.crew_technician_id();
  v_out      jsonb;
begin
  if v_employer is null then
    return null;
  end if;
  select jsonb_build_object(
    'date', p_date,
    'me', (
      select jsonb_build_object('id', t.id, 'name', t.name, 'role', t.role, 'status', t.status)
      from public.technicians t where t.id = v_tech
    ),
    'crew', (
      select jsonb_build_object('id', c.id, 'name', c.name, 'color', c.color, 'day_start', c.day_start)
      from public.crews c where c.id = v_crew and c.user_id = v_employer
    ),
    'business', (
      select jsonb_build_object('name', b.company_name, 'phone', b.phone, 'work_start_time', b.work_start_time)
      from public.business_settings b where b.user_id = v_employer
    ),
    'teammates', coalesce((
      select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'role', t.role) order by t.name)
      from public.technicians t
      where t.user_id = v_employer and t.crew_id = v_crew
        and t.is_active and t.archived_at is null and t.id is distinct from v_tech
    ), '[]'::jsonb),
    'day_note', (
      select d.body from public.dispatch_notes d
      where d.user_id = v_employer and d.date = p_date and d.crew_id is null
    ),
    'crew_note', (
      select d.body from public.dispatch_notes d
      where d.user_id = v_employer and d.date = p_date and d.crew_id = v_crew
    ),
    'stops', coalesce((
      select jsonb_agg(x.stop order by x.route_rank, x.start_key, x.created_at)
      from (
        select
          jsonb_build_object(
            'id', j.id,
            'title', j.title,
            'service_type', j.service_type,
            'scheduled_date', j.scheduled_date,
            'start_time', j.start_time,
            'duration_minutes', j.duration_minutes,
            'crew_size', j.crew_size,
            'status', j.status,
            'started_at', j.started_at,
            'completed_at', j.completed_at,
            'actual_minutes', j.actual_minutes,
            'on_my_way_at', j.on_my_way_at,
            'route_order', j.route_order,
            'updated_at', j.updated_at,
            'notes', j.notes,
            'completion_summary', j.completion_summary,
            'completion_issue', j.completion_issue,
            'personal', (j.technician_id is not null and j.technician_id = v_tech),
            'checklist', public.job_form_summary(j.id, j.user_id),
            'customer', case when cu.id is null then null else
              jsonb_build_object('name', cu.name, 'phone', cu.phone) end,
            'property', case when p.id is null then null else
              jsonb_build_object('address', p.address, 'lat', p.lat, 'lng', p.lng) end
          ) as stop,
          coalesce(j.route_order, 999999) as route_rank,
          coalesce(j.start_time::text, '99:99') as start_key,
          j.created_at
        from public.jobs j
        left join public.customers cu on cu.id = j.customer_id
        left join public.properties p on p.id = j.property_id
        where j.user_id = v_employer
          and public.crew_assignment_covers(j.crew_id, j.technician_id, v_crew, v_tech)
          and j.scheduled_date = p_date
      ) x
    ), '[]'::jsonb)
  ) into v_out;
  return v_out;
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_employer()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select t.user_id from public.technicians t
  where t.auth_user_id = auth.uid() and t.is_active and t.archived_at is null limit 1
$function$;

CREATE OR REPLACE FUNCTION public.crew_issue_invite(p_technician_id uuid, p_hours integer DEFAULT 72)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_code text := '';
  v_exp  timestamptz;
  v_byte int;
  v_alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
begin
  if auth.uid() is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.technicians t
    where t.id = p_technician_id and t.user_id = auth.uid() and t.archived_at is null
  ) then
    raise exception 'no such person on your roster' using errcode = '42501';
  end if;

  while length(v_code) < 8 loop
    v_byte := get_byte(extensions.gen_random_bytes(1), 0);
    if v_byte < 248 then
      v_code := v_code || substr(v_alphabet, 1 + (v_byte % 31), 1);
    end if;
  end loop;

  v_exp := now() + make_interval(hours => greatest(1, least(720, p_hours)));

  update public.technicians
     set invite_code = v_code, invite_expires_at = v_exp
   where id = p_technician_id;

  return jsonb_build_object('code', v_code, 'expires_at', v_exp);
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_job_field_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.uid() is null or auth.uid() = new.user_id then
    return new;
  end if;
  if public.crew_employer() is null then
    return new;
  end if;

  if row(new.user_id, new.customer_id, new.property_id, new.quote_id, new.recurrence_id,
         new.title, new.service_type, new.scheduled_date, new.start_time, new.end_time,
         new.duration_minutes, new.crew_size, new.price, new.notes, new.crew_id,
         new.technician_id, new.route_order, new.is_initial_visit)
     is distinct from
     row(old.user_id, old.customer_id, old.property_id, old.quote_id, old.recurrence_id,
         old.title, old.service_type, old.scheduled_date, old.start_time, old.end_time,
         old.duration_minutes, old.crew_size, old.price, old.notes, old.crew_id,
         old.technician_id, old.route_order, old.is_initial_visit)
  then
    raise exception 'crew may only change a visit''s status and its timestamps'
      using errcode = '42501';
  end if;

  if new.status not in ('scheduled', 'in_progress', 'completed') then
    raise exception 'crew may not set a visit to %', new.status using errcode = '42501';
  end if;

  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_job_forms(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_crew uuid := public.crew_crew_id();
  v_tech uuid := public.crew_technician_id();
  v_job public.jobs;
  v_out jsonb;
begin
  if v_employer is null or v_tech is null then return null; end if;
  select * into v_job from public.jobs
  where id = p_job_id and user_id = v_employer
    and public.crew_assignment_covers(crew_id, technician_id, v_crew, v_tech);
  if not found then return null; end if;

  perform public.ensure_job_forms(p_job_id);

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', jf.id,
    'template_name', jf.template_name,
    'fields', jf.fields,
    'waived', jf.waived_at is not null,
    'frozen', v_job.status = 'completed',
    'responses', coalesce((
      select jsonb_agg(jsonb_build_object(
        'field_id', r.field_id,
        'value_text', r.value_text,
        'value_number', r.value_number,
        'value_bool', r.value_bool,
        'value_date', r.value_date,
        'value_time', r.value_time,
        'value_choice', r.value_choice,
        'answered_role', r.answered_role,
        'answered_at', r.answered_at,
        'answered_name', coalesce(
          (select t.name from public.technicians t
           where t.auth_user_id = r.answered_by and t.user_id = jf.user_id
           limit 1),
          'Office'),
        'photos', coalesce((
          select jsonb_agg(jsonb_build_object('id', ph.id, 'storage_path', ph.storage_path)
                           order by p.created_at)
          from public.job_form_response_photos p
          join public.job_photos ph on ph.id = p.photo_id and ph.user_id = p.user_id
          where p.response_id = r.id and p.user_id = r.user_id
        ), '[]'::jsonb)
      ) order by r.created_at)
      from public.job_form_responses r
      where r.form_id = jf.id and r.user_id = jf.user_id
    ), '[]'::jsonb)
  ) order by jf.created_at), '[]'::jsonb)
  into v_out
  from public.job_forms jf
  where jf.job_id = v_job.id and jf.user_id = v_job.user_id;

  return v_out;
end;
$function$;

CREATE OR REPLACE FUNCTION public.crew_job_messages(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_crew     uuid := public.crew_crew_id();
  v_tech     uuid := public.crew_technician_id();
  v_uid      uuid := auth.uid();
  v_job      record;
  v_msgs     jsonb;
  v_high     timestamptz;
begin
  if v_employer is null or v_tech is null then
    return null;
  end if;

  select j.id, j.title, j.scheduled_date, j.status, c.name as customer_name
    into v_job
    from public.jobs j
    left join public.customers c on c.id = j.customer_id
   where j.id = p_job_id and j.user_id = v_employer
     and public.crew_assignment_covers(j.crew_id, j.technician_id, v_crew, v_tech);

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  select jsonb_agg(m.msg order by m.created_at), max(m.created_at)
    into v_msgs, v_high
    from (
      select jsonb_build_object(
               'id', x.id,
               'body', x.body,
               'author_kind', x.author_kind,
               'author_name', x.author_name,
               'author_technician_id', x.author_technician_id,
               'event_type', x.event_type,
               'mine', x.created_by is not distinct from v_uid,
               'created_at', x.created_at
             ) as msg,
             x.created_at
        from public.crew_messages x
       where x.job_id = v_job.id and x.user_id = v_employer
    ) m;

  if v_high is not null then
    insert into public.crew_message_reads (user_id, job_id, reader_id, last_read_at)
    values (v_employer, v_job.id, v_uid, v_high)
    on conflict (job_id, reader_id) do update
      set last_read_at = greatest(public.crew_message_reads.last_read_at, excluded.last_read_at);
  end if;

  return jsonb_build_object(
    'ok', true,
    'job_id', v_job.id,
    'title', v_job.title,
    'customer_name', v_job.customer_name,
    'scheduled_date', v_job.scheduled_date,
    'status', v_job.status,
    'messages', coalesce(v_msgs, '[]'::jsonb)
  );
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_message_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid  uuid := auth.uid();
  v_tech uuid;
  v_name text;
begin
  if new.event_type is not null then
    new.author_kind          := 'system';
    new.author_technician_id := null;
    new.created_by           := null;
    new.author_name          := coalesce(nullif(btrim(new.author_name), ''), 'Schedule');
    return new;
  end if;

  if v_uid is null then
    raise exception 'a message needs a signed-in author' using errcode = '42501';
  end if;

  if v_uid = new.user_id then
    select coalesce(nullif(btrim(b.owner_name), ''), nullif(btrim(b.company_name), ''), 'Office')
      into v_name
      from public.business_settings b
     where b.user_id = new.user_id;
    new.author_kind          := 'owner';
    new.author_technician_id := null;
    new.created_by           := v_uid;
    new.author_name          := coalesce(v_name, 'Office');
    return new;
  end if;

  if public.crew_employer() is distinct from new.user_id then
    raise exception 'you cannot post to that visit' using errcode = '42501';
  end if;
  v_tech := public.crew_technician_id();
  select t.name into v_name from public.technicians t where t.id = v_tech;

  new.author_kind          := 'crew';
  new.author_technician_id := v_tech;
  new.created_by           := v_uid;
  new.author_name          := coalesce(nullif(btrim(v_name), ''), 'Crew');
  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_message_inbox()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_crew     uuid := public.crew_crew_id();
  v_tech     uuid := public.crew_technician_id();
  v_uid      uuid := auth.uid();
begin
  if v_employer is null or v_tech is null then
    return null;
  end if;

  return coalesce((
    select jsonb_agg(t.row order by t.unread desc, t.last_at desc)
    from (
      select jsonb_build_object(
               'job_id', j.id,
               'title', j.title,
               'customer_name', c.name,
               'scheduled_date', j.scheduled_date,
               'status', j.status,
               'unread', count(*) filter (
                 where m.created_at > coalesce(r.last_read_at, '-infinity'::timestamptz)
                   and m.created_by is distinct from v_uid
                   and m.author_kind <> 'system'),
               'last_at', max(m.created_at),
               'last_author', (array_agg(m.author_name order by m.created_at desc))[1],
               'last_body',   (array_agg(m.body        order by m.created_at desc))[1]
             ) as row,
             count(*) filter (
               where m.created_at > coalesce(r.last_read_at, '-infinity'::timestamptz)
                 and m.created_by is distinct from v_uid
                 and m.author_kind <> 'system') as unread,
             max(m.created_at) as last_at
        from public.crew_messages m
        join public.jobs j on j.id = m.job_id
        left join public.customers c on c.id = j.customer_id
        left join public.crew_message_reads r on r.job_id = j.id and r.reader_id = v_uid
       where m.user_id = v_employer
         and j.user_id = v_employer
         and public.crew_assignment_covers(j.crew_id, j.technician_id, v_crew, v_tech)
         and m.created_at > now() - interval '30 days'
       group by j.id, j.title, c.name, j.scheduled_date, j.status
    ) t
  ), '[]'::jsonb);
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_message_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_job record;
begin
  if new.author_kind <> 'crew' then
    return new;
  end if;
  if exists (
    select 1 from public.notifications n
     where n.user_id = new.user_id and n.type = 'crew_message'
       and n.entity_id = new.job_id and n.read = false
  ) then
    return new;
  end if;

  select j.customer_id, j.title, c.name as customer_name
    into v_job
    from public.jobs j
    left join public.customers c on c.id = j.customer_id
   where j.id = new.job_id;

  insert into public.notifications (user_id, type, title, body, customer_id, entity_type, entity_id, href)
  values (
    new.user_id,
    'crew_message',
    new.author_name || ' — ' || coalesce(nullif(btrim(v_job.customer_name), ''), v_job.title, 'a visit'),
    left(new.body, 140),
    v_job.customer_id,
    'job',
    new.job_id,
    '/dashboard/schedule?job=' || new.job_id::text
  );
  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_message_schedule_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_body text;
begin
  if new.scheduled_date is not distinct from old.scheduled_date
     and new.start_time is not distinct from old.start_time then
    return new;
  end if;
  if not exists (select 1 from public.crew_messages m where m.job_id = new.id) then
    return new;
  end if;

  if new.scheduled_date is distinct from old.scheduled_date then
    v_body := 'Schedule changed — '
           || to_char(old.scheduled_date, 'Dy Mon FMDD')
           || ' → ' || to_char(new.scheduled_date, 'Dy Mon FMDD');
  else
    v_body := 'Start time changed — '
           || coalesce(to_char(date '2000-01-01' + old.start_time, 'FMHH12:MI AM'), 'no set time')
           || ' → ' || coalesce(to_char(date '2000-01-01' + new.start_time, 'FMHH12:MI AM'), 'no set time');
  end if;

  insert into public.crew_messages (user_id, job_id, body, author_kind, author_name, event_type)
  values (new.user_id, new.id, v_body, 'system', 'Schedule', 'schedule_changed');
  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_my_availability()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_tech     uuid := public.crew_technician_id();
begin
  if v_employer is null or v_tech is null then
    return null;
  end if;
  return jsonb_build_object(
    'pattern', coalesce((
      select jsonb_agg(jsonb_build_object(
        'weekday', w.weekday, 'available', w.available,
        'start_time', w.start_time, 'end_time', w.end_time
      ) order by w.weekday)
      from public.worker_availability w
      where w.technician_id = v_tech and w.user_id = v_employer
    ), '[]'::jsonb),
    'time_off', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', p.id, 'date', p.date, 'hours', p.hours,
        'kind', p.kind, 'status', p.status
      ) order by p.date desc)
      from public.pto_entries p
      where p.technician_id = v_tech and p.user_id = v_employer
        and p.date >= current_date - 60
    ), '[]'::jsonb)
  );
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_post_message(p_job_id uuid, p_body text, p_client_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_crew     uuid := public.crew_crew_id();
  v_tech     uuid := public.crew_technician_id();
  v_uid      uuid := auth.uid();
  v_job      uuid;
  v_body     text := btrim(coalesce(p_body, ''));
  v_row      public.crew_messages%rowtype;
begin
  if v_employer is null or v_tech is null then
    return null;
  end if;
  if v_body = '' then
    return jsonb_build_object('ok', false, 'reason', 'empty');
  end if;
  if char_length(v_body) > 2000 then
    return jsonb_build_object('ok', false, 'reason', 'too_long');
  end if;

  select j.id into v_job
    from public.jobs j
   where j.id = p_job_id and j.user_id = v_employer
     and public.crew_assignment_covers(j.crew_id, j.technician_id, v_crew, v_tech);
  if v_job is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  insert into public.crew_messages (user_id, job_id, body, author_kind, author_name, client_token)
  values (v_employer, v_job, v_body, 'crew', 'Crew', nullif(btrim(coalesce(p_client_token, '')), ''))
  on conflict (job_id, created_by, client_token) where client_token is not null do nothing
  returning * into v_row;

  if v_row.id is null then
    select * into v_row from public.crew_messages
     where job_id = v_job and created_by = v_uid
       and client_token = nullif(btrim(coalesce(p_client_token, '')), '')
     limit 1;
  end if;
  if v_row.id is null then
    return jsonb_build_object('ok', false, 'reason', 'failed');
  end if;

  insert into public.crew_message_reads (user_id, job_id, reader_id, last_read_at)
  values (v_employer, v_job, v_uid, v_row.created_at)
  on conflict (job_id, reader_id) do update
    set last_read_at = greatest(public.crew_message_reads.last_read_at, excluded.last_read_at);

  return jsonb_build_object('ok', true, 'message', jsonb_build_object(
    'id', v_row.id,
    'body', v_row.body,
    'author_kind', v_row.author_kind,
    'author_name', v_row.author_name,
    'author_technician_id', v_row.author_technician_id,
    'event_type', v_row.event_type,
    'mine', true,
    'created_at', v_row.created_at
  ));
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_redeem_invite(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tech public.technicians%rowtype;
begin
  if auth.uid() is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if exists (select 1 from public.business_settings b where b.user_id = auth.uid()) then
    raise exception 'this account owns a business — it cannot also join one as crew' using errcode = '42501';
  end if;
  if exists (select 1 from public.technicians t where t.auth_user_id = auth.uid()) then
    raise exception 'this account is already linked to an employee' using errcode = '42501';
  end if;

  select * into v_tech from public.technicians t
  where t.invite_code = upper(btrim(p_code)) limit 1;

  if v_tech.id is null then
    raise exception 'that code is not valid' using errcode = '42501';
  end if;
  if v_tech.invite_expires_at is null or v_tech.invite_expires_at < now() then
    raise exception 'that code has expired — ask for a new one' using errcode = '42501';
  end if;
  if v_tech.archived_at is not null or not v_tech.is_active then
    raise exception 'that code is not valid' using errcode = '42501';
  end if;
  if v_tech.auth_user_id is not null then
    raise exception 'that code has already been used' using errcode = '42501';
  end if;

  update public.technicians
     set auth_user_id = auth.uid(), invite_code = null, invite_expires_at = null
   where id = v_tech.id;

  return jsonb_build_object('technician_id', v_tech.id, 'name', v_tech.name);
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_request_time_off(p_date date, p_hours numeric, p_kind text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_tech     uuid := public.crew_technician_id();
  v_name     text;
  v_id       uuid;
begin
  if v_employer is null or v_tech is null then
    raise exception 'you are not on an active crew' using errcode = '42501';
  end if;
  if p_date is null or p_date < current_date then
    return jsonb_build_object('ok', false, 'reason', 'past_date');
  end if;
  if p_hours is null or p_hours <= 0 or p_hours > 24 then
    return jsonb_build_object('ok', false, 'reason', 'bad_hours');
  end if;
  -- 'holiday' is owner-applied from the holiday calendar, never requested.
  if p_kind not in ('vacation', 'sick', 'personal', 'bereavement') then
    return jsonb_build_object('ok', false, 'reason', 'bad_kind');
  end if;

  begin
    insert into public.pto_entries
      (user_id, technician_id, date, hours, kind, is_paid, hourly_rate, notes, status)
    values (
      v_employer, v_tech, p_date, p_hours, p_kind,
      false, null, nullif(left(trim(coalesce(p_note, '')), 500), ''), 'requested'
    )
    returning id into v_id;
  exception when unique_violation then
    return jsonb_build_object('ok', false, 'reason', 'already_booked');
  end;

  select t.name into v_name from public.technicians t where t.id = v_tech;
  insert into public.notifications (user_id, type, title, body, entity_type, entity_id, href)
  values (
    v_employer, 'time_off_requested', 'Time-off request',
    coalesce(v_name, 'A worker') || ' asked for ' || to_char(p_date, 'Mon FMDD') ||
      ' off (' || p_hours || ' h, ' || p_kind || ').',
    'pto_entry', v_id, '/dashboard/dispatch/time-off?tab=requests'
  );

  return jsonb_build_object('ok', true, 'id', v_id);
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_revoke_access(p_technician_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.technicians t where t.id = p_technician_id and t.user_id = auth.uid()
  ) then
    raise exception 'no such person on your roster' using errcode = '42501';
  end if;
  update public.technicians
     set auth_user_id = null, invite_code = null, invite_expires_at = null, invite_sent_at = null
   where id = p_technician_id;
  return jsonb_build_object('revoked', true);
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_save_form_response(p_form_id uuid, p_field_id uuid, p_value_text text, p_value_number numeric, p_value_bool boolean, p_value_date date, p_value_time time without time zone, p_value_choice text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_crew uuid := public.crew_crew_id();
  v_tech uuid := public.crew_technician_id();
  v_form public.job_forms;
  v_job public.jobs;
  v_empty boolean;
begin
  if v_employer is null or v_tech is null then
    return jsonb_build_object('ok', false, 'reason', 'not_yours');
  end if;
  select * into v_form from public.job_forms where id = p_form_id and user_id = v_employer;
  if not found then return jsonb_build_object('ok', false, 'reason', 'not_yours'); end if;
  select * into v_job from public.jobs
  where id = v_form.job_id and user_id = v_employer
    and public.crew_assignment_covers(crew_id, technician_id, v_crew, v_tech);
  if not found then return jsonb_build_object('ok', false, 'reason', 'not_yours'); end if;
  if v_job.status = 'cancelled' then
    return jsonb_build_object('ok', false, 'reason', 'cancelled');
  end if;
  if v_job.status = 'completed' then
    return jsonb_build_object('ok', false, 'reason', 'completed');
  end if;

  v_empty := p_value_text is null and p_value_number is null and p_value_bool is null
         and p_value_date is null and p_value_time is null and p_value_choice is null;

  if v_empty then
    delete from public.job_form_responses
    where form_id = v_form.id and user_id = v_employer and field_id = p_field_id;
    return jsonb_build_object('ok', true, 'cleared', true);
  end if;

  insert into public.job_form_responses as r
    (user_id, form_id, field_id, value_text, value_number, value_bool,
     value_date, value_time, value_choice, answered_by, answered_role, answered_at)
  values
    (v_employer, v_form.id, p_field_id, p_value_text, p_value_number, p_value_bool,
     p_value_date, p_value_time, p_value_choice, auth.uid(), 'crew', now())
  on conflict (form_id, field_id) do update set
    value_text = excluded.value_text,
    value_number = excluded.value_number,
    value_bool = excluded.value_bool,
    value_date = excluded.value_date,
    value_time = excluded.value_time,
    value_choice = excluded.value_choice,
    answered_by = excluded.answered_by,
    answered_role = excluded.answered_role,
    answered_at = now();

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.crew_set_completion_record(p_job_id uuid, p_summary text DEFAULT NULL::text, p_issue text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_crew     uuid := public.crew_crew_id();
  v_tech     uuid := public.crew_technician_id();
  v_summary  text := nullif(btrim(coalesce(p_summary, '')), '');
  v_issue    text := nullif(btrim(coalesce(p_issue, '')), '');
  v_prev     text;
  v_job      record;
begin
  if v_employer is null or v_tech is null then
    raise exception 'you are not on the active roster' using errcode = '42501';
  end if;

  v_summary := left(v_summary, 500);
  v_issue   := left(v_issue, 500);

  select j.completion_issue into v_prev
    from public.jobs j
   where j.id = p_job_id and j.user_id = v_employer
     and public.crew_assignment_covers(j.crew_id, j.technician_id, v_crew, v_tech)
     and j.status <> 'cancelled';

  update public.jobs j
     set completion_summary = v_summary,
         completion_issue   = v_issue
   where j.id = p_job_id
     and j.user_id = v_employer
     and public.crew_assignment_covers(j.crew_id, j.technician_id, v_crew, v_tech)
     and j.status <> 'cancelled'
  returning j.id, j.title, j.customer_id into v_job;

  if v_job.id is null then
    return jsonb_build_object('ok', false, 'reason', 'not_yours');
  end if;

  if v_issue is not null and v_prev is distinct from v_issue then
    insert into public.notifications (user_id, type, title, body, customer_id, entity_type, entity_id, href)
    select v_employer, 'crew_visit_issue', 'Your crew flagged something',
           coalesce(v_job.title, 'A visit') || ': ' || v_issue,
           v_job.customer_id, 'job', v_job.id, '/dashboard/dispatch'
     where not exists (
       select 1 from public.notifications n
        where n.user_id = v_employer and n.type = 'crew_visit_issue' and n.entity_id = v_job.id
     );
  end if;

  return jsonb_build_object('ok', true);
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_set_day_availability(p_weekday smallint, p_available boolean, p_start_time time without time zone DEFAULT NULL::time without time zone, p_end_time time without time zone DEFAULT NULL::time without time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_tech     uuid := public.crew_technician_id();
begin
  if v_employer is null or v_tech is null then
    raise exception 'you are not on an active crew' using errcode = '42501';
  end if;
  if p_weekday is null or p_weekday < 0 or p_weekday > 6 then
    return jsonb_build_object('ok', false, 'reason', 'bad_weekday');
  end if;
  if p_available and (p_start_time is null or p_end_time is null or p_end_time <= p_start_time) then
    return jsonb_build_object('ok', false, 'reason', 'bad_window');
  end if;

  insert into public.worker_availability
    (user_id, technician_id, weekday, available, start_time, end_time)
  values (
    v_employer, v_tech, p_weekday, p_available,
    case when p_available then p_start_time end,
    case when p_available then p_end_time end
  )
  on conflict (technician_id, weekday) do update
    set available  = excluded.available,
        start_time = excluded.start_time,
        end_time   = excluded.end_time,
        updated_at = now();
  return jsonb_build_object('ok', true);
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_set_visit_status(p_job_id uuid, p_status text, p_base_updated_at timestamp with time zone, p_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_completed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actual_minutes integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_crew     uuid := public.crew_crew_id();
  v_tech     uuid := public.crew_technician_id();
  v_updated  timestamptz;
begin
  if v_employer is null or v_tech is null then
    raise exception 'you are not on the active roster' using errcode = '42501';
  end if;
  -- The field lifecycle, and only it. 'cancelled' is a business decision: a
  -- worker who cannot finish leaves the visit open for the office.
  if p_status not in ('scheduled', 'in_progress', 'completed') then
    raise exception 'crew may not set a visit to %', p_status using errcode = '42501';
  end if;

  -- Assignment is re-checked HERE because this function is DEFINER and so runs
  -- past the RLS that would otherwise do it. Optimistic concurrency rides in the
  -- same predicate: if the office moved the visit while the phone held an old
  -- copy, nothing matches and the caller is told, rather than overwriting them.
  update public.jobs j
     set status         = p_status,
         started_at     = p_started_at,
         completed_at   = p_completed_at,
         actual_minutes = p_actual_minutes
   where j.id = p_job_id
     and j.user_id = v_employer
     and public.crew_assignment_covers(j.crew_id, j.technician_id, v_crew, v_tech)
     and j.updated_at = p_base_updated_at
  returning j.updated_at into v_updated;

  if v_updated is null then
    return jsonb_build_object('ok', false, 'reason', 'stale');
  end if;
  return jsonb_build_object('ok', true, 'updated_at', v_updated);
end
$function$;

CREATE OR REPLACE FUNCTION public.crew_technician_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select t.id from public.technicians t
  where t.auth_user_id = auth.uid() and t.is_active and t.archived_at is null limit 1
$function$;

CREATE OR REPLACE FUNCTION public.crew_upcoming(p_from date, p_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employer uuid := public.crew_employer();
  v_crew     uuid := public.crew_crew_id();
  v_tech     uuid := public.crew_technician_id();
begin
  if v_employer is null then
    return null;
  end if;
  return coalesce((
    select jsonb_agg(g.day_summary order by g.day)
    from (
      select jsonb_build_object(
               'date', j.scheduled_date,
               'stops', count(*),
               'done', count(*) filter (where j.status = 'completed'),
               'minutes', coalesce(sum(coalesce(j.duration_minutes, 45)), 0)
             ) as day_summary,
             j.scheduled_date as day
      from public.jobs j
      where j.user_id = v_employer
        and public.crew_assignment_covers(j.crew_id, j.technician_id, v_crew, v_tech)
        and j.status <> 'cancelled'
        and j.scheduled_date >= p_from
        and j.scheduled_date < p_from + greatest(1, least(31, p_days))
      group by j.scheduled_date
    ) g
  ), '[]'::jsonb);
end
$function$;

CREATE OR REPLACE FUNCTION public.crews_block_delete_with_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if exists (select 1 from public.jobs j where j.crew_id = old.id)
     or exists (select 1 from public.technician_crew_history h where h.crew_id = old.id)
  then
    raise exception 'this crew has history — deactivate it instead of deleting'
      using errcode = '23514';
  end if;
  return old;
end
$function$;

CREATE OR REPLACE FUNCTION public.crews_lead_is_member()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.lead_technician_id is null then
    return new;
  end if;
  if not exists (
    select 1 from public.technicians t
    where t.id = new.lead_technician_id
      and t.user_id = new.user_id
      and t.crew_id = new.id
      and t.is_active
      and t.archived_at is null
  ) then
    raise exception 'the crew lead must be an active member of this crew'
      using errcode = '23514';
  end if;
  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.crm_stamp_review_requested()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.template in ('review_request', 'review_chase')
     and new.status = 'sent'
     and new.customer_id is not null then
    update public.customers
      set review_requested_at = coalesce(review_requested_at, new.created_at)
      where id = new.customer_id and reviewed_at is null and review_declined_at is null;
  end if;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.crm_sync_referral()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.referred_by_customer_id is not null
     and new.referred_by_customer_id <> new.id
     and (TG_OP = 'INSERT' or new.referred_by_customer_id is distinct from old.referred_by_customer_id) then
    insert into public.referrals (user_id, referrer_customer_id, referred_customer_id, referred_name, status, joined_at)
      values (new.user_id, new.referred_by_customer_id, new.id, new.name, 'joined', coalesce(new.created_at, now()))
      on conflict (referrer_customer_id, referred_customer_id) where referred_customer_id is not null
      do update set status    = case when referrals.status = 'invited' then 'joined' else referrals.status end,
                    joined_at = coalesce(referrals.joined_at, excluded.joined_at);
  end if;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.crm_touch_last_contacted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.direction = 'outbound' and new.customer_id is not null then
    update public.customers
      set last_contacted_at = greatest(coalesce(last_contacted_at, '-infinity'::timestamptz), new.created_at)
      where id = new.customer_id;
  end if;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.current_app_role()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when auth.uid() is null then 'none'
    when exists (select 1 from public.business_settings b where b.user_id = auth.uid()) then 'owner'
    when public.crew_employer() is not null then 'crew'
    else 'none'
  end
$function$;

CREATE OR REPLACE FUNCTION public.custom_field_definition_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.field_key is distinct from old.field_key then
    raise exception 'a custom field''s key cannot change once created'
      using errcode = 'check_violation';
  end if;
  if new.entity is distinct from old.entity then
    raise exception 'a custom field cannot be moved to a different kind of record'
      using errcode = 'check_violation';
  end if;
  -- Changing the type of a field that already holds answers would silently
  -- reinterpret them. The composite FK would abort this anyway; saying so plainly
  -- is the difference between a fixable message and a constraint-name dump.
  if new.field_type is distinct from old.field_type
     and exists (select 1 from public.custom_field_values v where v.definition_id = old.id) then
    raise exception 'this field already holds answers, so its type cannot change — archive it and create a new one'
      using errcode = 'check_violation';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.custom_field_value_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_archived timestamptz;
  v_type     text;
  v_options  jsonb;
begin
  select archived_at, field_type, options
    into v_archived, v_type, v_options
    from public.custom_field_definitions
   where id = new.definition_id;

  -- The FK guarantees a parent exists; this is the belt to its braces and keeps
  -- the failure legible if the FK is ever relaxed.
  if not found then
    raise exception 'custom field definition % not found', new.definition_id
      using errcode = 'foreign_key_violation';
  end if;

  -- ARCHIVED: existing values stay readable and editable-to-empty, but no NEW
  -- answer may be recorded against a field the owner has retired. Historical
  -- truth is the point of archiving; letting new writes land would make an
  -- archived field a live field with a confusing label.
  if v_archived is not null then
    raise exception 'custom field "%" is archived and no longer accepts values', new.definition_id
      using errcode = 'check_violation';
  end if;

  -- DROPDOWN VALIDITY: the stored text must be one of the option slugs the
  -- definition currently offers. Removing an option therefore blocks NEW writes
  -- of it while leaving every row already holding it untouched — which is the
  -- honest behaviour, and why this is checked on write and never on read.
  if v_type = 'select' then
    if not exists (
      select 1 from jsonb_array_elements(v_options) o
       where o->>'value' = new.value_text
    ) then
      raise exception 'value % is not one of the choices offered by this field', new.value_text
        using errcode = 'check_violation';
    end if;
  end if;

  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.ensure_job_forms(p_job_id uuid)
 RETURNS SETOF job_forms
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_job public.jobs;
  v_uid uuid := auth.uid();
  v_employer uuid;
  v_crew uuid;
  v_tech uuid;
  v_default record;
begin
  select * into v_job from public.jobs where id = p_job_id;
  if not found then return; end if;

  if v_uid is not null and v_uid <> v_job.user_id then
    v_employer := public.crew_employer();
    v_crew := public.crew_crew_id();
    v_tech := public.crew_technician_id();
    if v_employer is null or v_employer <> v_job.user_id
       or v_tech is null
       or not public.crew_assignment_covers(v_job.crew_id, v_job.technician_id, v_crew, v_tech) then
      return; -- not yours: say nothing, mint nothing
    end if;
  end if;

  select * into v_default from public.job_form_default_template(v_job);
  if v_default.template_id is not null then
    insert into public.job_forms (user_id, job_id, template_id, template_name, fields, source)
    select v_job.user_id, v_job.id, ft.id, ft.name,
           public.form_template_snapshot(ft.id, v_job.user_id), v_default.source
    from public.form_templates ft
    where ft.id = v_default.template_id and ft.user_id = v_job.user_id
    on conflict (job_id, template_id) do nothing;
  end if;

  return query select * from public.job_forms
    where job_id = v_job.id and user_id = v_job.user_id
    order by created_at;
end;
$function$;

CREATE OR REPLACE FUNCTION public.ensure_pricing_config_version(p_user uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  s    record;
  w    record;
begin
  if p_user is null then return null; end if;

  -- TENANT GUARD (2026-08-10): a signed-in caller may only record a version for
  -- THEMSELVES. auth.uid() is null under service_role/trigger contexts, which
  -- stay unaffected. Without this, EXECUTE alone let any authenticated account —
  -- including a crew member with zero table access — write into another
  -- business's pricing history (reproduced: owner versions 3 -> 4).
  if auth.uid() is not null and p_user is distinct from auth.uid() then
    return null;
  end if;

  select
    case when coalesce(pricing_base_charge, 0) > 0      then pricing_base_charge      else 28  end as base_charge,
    case when coalesce(pricing_mow_rate, 0) > 0         then pricing_mow_rate         else 15  end as mow_rate_per_1000,
    0.8::numeric  as budget_mult,
    0.92::numeric as market_mult,
    case when coalesce(pricing_recommended_mult, 0) > 0 then pricing_recommended_mult else 1.0 end as recommended_mult,
    case when coalesce(pricing_premium_mult, 0) > 0     then pricing_premium_mult     else 1.2 end as premium_mult,
    case when coalesce(pricing_travel_rate, 0) > 0      then pricing_travel_rate      else 1.5 end as travel_rate_per_km,
    coalesce(crew_cost_per_hour, 40)                        as crew_cost_per_hour,
    coalesce(fee_recovery_percent, 3)                       as fee_recovery_percent,
    coalesce(payment_fee_strategy, 'global_price_increase') as payment_fee_strategy
  into w
  from public.business_settings where user_id = p_user;

  if not found then return null; end if;

  select * into s from public.pricing_config_versions
   where user_id = p_user order by valid_from desc limit 1;

  if found
     and s.engine_version = 'v1'
     and s.base_charge          = w.base_charge
     and s.mow_rate_per_1000    = w.mow_rate_per_1000
     and s.budget_mult          = w.budget_mult
     and s.market_mult          = w.market_mult
     and s.recommended_mult     = w.recommended_mult
     and s.premium_mult         = w.premium_mult
     and s.travel_rate_per_km   = w.travel_rate_per_km
     and s.crew_cost_per_hour   = w.crew_cost_per_hour
     and s.fee_recovery_percent = w.fee_recovery_percent
     and s.payment_fee_strategy = w.payment_fee_strategy
  then
    return s.id;
  end if;

  insert into public.pricing_config_versions (
    user_id, valid_from, source, note, engine_version,
    base_charge, mow_rate_per_1000, budget_mult, market_mult,
    recommended_mult, premium_mult, travel_rate_per_km,
    crew_cost_per_hour, fee_recovery_percent, payment_fee_strategy
  ) values (
    p_user, now(), 'recorded', 'Recorded by ensure_pricing_config_version on a detected settings change.', 'v1',
    w.base_charge, w.mow_rate_per_1000, w.budget_mult, w.market_mult,
    w.recommended_mult, w.premium_mult, w.travel_rate_per_km,
    w.crew_cost_per_hour, w.fee_recovery_percent, w.payment_fee_strategy
  ) returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fanout_integration_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.webhook_deliveries (user_id, endpoint_id, event_id, event, payload)
  select new.user_id, e.id, new.id, new.event, new.payload
  from public.webhook_endpoints e
  where e.user_id = new.user_id and e.active
    and ('*' = any(e.events) or new.event = any(e.events));
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.find_customer_by_phone(p_phone text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d text; result json;
begin
  d := right(regexp_replace(coalesce(p_phone, ''), '\D', '', 'g'), 10);
  if length(d) < 10 then return null; end if;
  select to_json(c) into result from (
    select id, user_id, sms_opt_in, name from public.customers
    where phone is not null and right(regexp_replace(phone, '\D', '', 'g'), 10) = d
    order by created_at desc limit 1
  ) c;
  return result;
end; $function$;

CREATE OR REPLACE FUNCTION public.find_inbound_sms_customer(p_phone text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d text; result json;
begin
  d := right(regexp_replace(coalesce(p_phone, ''), '\D', '', 'g'), 10);
  if length(d) < 10 then return null; end if;
  select to_json(c) into result from (
    select cu.id, cu.user_id, cu.sms_opt_in, cu.name
    from public.customers cu
    join public.platform_capabilities pc
      on pc.user_id = cu.user_id and pc.inbound_sms
    where cu.phone is not null
      and right(regexp_replace(cu.phone, '\D', '', 'g'), 10) = d
    order by cu.created_at desc limit 1
  ) c;
  return result;
end; $function$;

CREATE OR REPLACE FUNCTION public.find_portal_access_customers(p_email text)
 RETURNS TABLE(customer_id uuid, customer_name text, owner_id uuid)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select c.id, c.name, c.user_id
  from public.customers c
  where c.archived_at is null
    and c.email is not null
    and lower(trim(c.email)) = lower(trim(p_email))
$function$;

CREATE OR REPLACE FUNCTION public.form_options_ok(p jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select jsonb_typeof(p) = 'array'
     and jsonb_array_length(p) between 1 and 30
     and not exists (
       select 1 from jsonb_array_elements(p) e
       where jsonb_typeof(e) <> 'string'
          or char_length(e #>> '{}') not between 1 and 100
     )
$function$;

CREATE OR REPLACE FUNCTION public.form_template_snapshot(p_template_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'id', f.id,
           'position', f.position,
           'type', f.field_type,
           'label', f.label,
           'help', f.help_text,
           'required', case when f.required then true else null end,
           'options', f.options,
           'unit', f.unit,
           'photo_kind', f.photo_kind
         )) order by f.position, f.created_at, f.id), '[]'::jsonb)
  from public.form_template_fields f
  where f.template_id = p_template_id and f.user_id = p_user_id
$function$;

CREATE OR REPLACE FUNCTION public.get_booking_business(p_token text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result json;
begin
  select to_json(b) into result from (
    select company_name, owner_name, logo_url, phone, email_primary, website,
           pricing_base_charge, pricing_mow_rate, pricing_recommended_mult, pricing_premium_mult, pricing_travel_rate,
           payment_fee_strategy, fee_recovery_percent, gst_percent
    from public.business_settings
    where booking_token = p_token and booking_enabled = true
  ) b;
  return result;
end; $function$;

CREATE OR REPLACE FUNCTION public.get_portal_data(p_token text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_customer uuid; v_user uuid; result json;
begin
  select customer_id, user_id into v_customer, v_user
    from public.customer_portal_tokens where token = p_token and not revoked;
  if v_customer is null then return null; end if;
  select json_build_object(
    -- review_declined_at: the customer's own "No thanks", so it survives the session.
    'customer', (select to_json(c) from (select id, name, email, phone, address, city, province, postal_code, sms_opt_in, email_opt_in, reviewed_at, review_declined_at, autopay_enabled from public.customers where id = v_customer and user_id = v_user) c),
    -- service_seasons: buildServicePlans needs the owner's REAL season window.
    -- gst_number: CRA requires the supplier's registration number on a $30+ invoice
    -- for the customer to claim an ITC. Null when not registered; the PDFs print it
    -- only when gst_percent > 0 AND it is set.
    'business', (select to_json(b) from (select company_name, owner_name, phone, email_primary, email_secondary, website, logo_url, logo_scale, base_address, terms_text, review_url, coalesce(gst_percent,0) as gst_percent, gst_number, etransfer_email, service_seasons from public.business_settings where user_id = v_user) b),
    -- The owner's OWN catalogue — what this business actually sells. Drives the
    -- portal's "Request a service" tab, so it lists pool visits for a pool company
    -- and window cleaning for a window cleaner. Active only, in the owner's order.
    'services', coalesce((select json_agg(s order by s.sort_order, s.name) from (
      select name, category, default_rate, pricing_display_type, default_description, sort_order
      from public.service_templates
      where user_id = v_user and is_active
    ) s), '[]'::json),
    -- UNCHANGED — the primary property. Kept because Home/PropertyTab/PDF fallbacks
    -- read it today; 'properties' below is the addition, not a replacement.
    'property', (select to_json(p) from (select address, city, province, postal_code, lawn_sqft, fence_length, neighborhood, notes from public.properties where customer_id = v_customer and user_id = v_user order by is_primary desc nulls last, created_at asc limit 1) p),
    -- NEW — EVERY property this customer owns. `id` is the join key the quotes and
    -- invoices projections below now carry; without it a card cannot name its own
    -- address or area, and 'property' above can only ever answer for the primary.
    -- Same ordering as the singular so properties[0] === property.
    'properties', coalesce((select json_agg(p order by p.is_primary desc nulls last, p.created_at asc) from (
      select id, address, city, province, postal_code, lawn_sqft, fence_length, neighborhood, is_primary, created_at
      from public.properties where customer_id = v_customer and user_id = v_user
    ) p), '[]'::json),
    -- property_id (NEW): which property this quote is actually for. NULL on legacy
    -- rows (4 of 62 at time of writing) — the client falls back to qt.address text
    -- and suppresses any area claim rather than borrowing the primary's.
    'quotes', coalesce((select json_agg(q order by q.created_at desc) from (
      select qt.id, qt.quote_number, qt.service_type, qt.address, qt.property_id, qt.total, qt.initial_price, qt.subtotal,
             qt.weekly_price, qt.biweekly_price, qt.monthly_price, qt.notes, qt.status, qt.created_at,
             qt.issued_date, qt.crew_size, qt.hours, qt.travel_fee, qt.valid_until,
             qt.selected_option_id,
             -- accepted_price: what the customer CONSENTED to (selected option +
             -- travel, snapshotted at approval) — the scheduling deposit derives
             -- from this, never from a live total an edit could move.
             -- deposit_type/deposit_value: the scheduling-deposit rule.
             -- preferred_*: the customer's own scheduling REQUEST (a preference,
             -- never a booking) — shown back so a reload keeps what they told us.
             qt.accepted_price, qt.deposit_type, qt.deposit_value,
             qt.preferred_date, qt.preferred_date_2, qt.preferred_timing, qt.preferred_note,
             coalesce((select json_agg(o order by o.sort_order) from (
               select qo.id, qo.name, qo.description, qo.price, qo.sort_order, qo.is_recommended
               from public.quote_options qo where qo.quote_id = qt.id
             ) o), '[]'::json) as options,
             coalesce((select json_agg(a order by a.sort_order) from (
               select qa.id, qa.name, qa.description, qa.price, qa.sort_order, qa.is_selected
               from public.quote_addons qa where qa.quote_id = qt.id
             ) a), '[]'::json) as addons,
             coalesce((select json_agg(s order by s.sort_order) from (
               select qs.service_type, qs.quantity, qs.unit, qs.unit_price, qs.est_minutes,
                      qs.discount_type, qs.discount_value, qs.notes, qs.sort_order
               from public.quote_services qs where qs.quote_id = qt.id
             ) s), '[]'::json) as services
      from public.quotes qt where qt.customer_id = v_customer and qt.user_id = v_user and qt.status <> 'draft') q), '[]'::json),
    -- property_id (NEW): same reason. NULL is the honest answer for a combined
    -- invoice spanning properties — do not infer one.
    -- ⛔ `and status <> 'draft'` IS A PRIVACY PREDICATE, NOT A FILTER PREFERENCE.
    -- A draft is the owner's unfinished, unsent bill. Without this clause it was
    -- serialized into the customer's payload and read straight out of devtools —
    -- the portal only declined to RENDER it. Same predicate the quotes select
    -- above has always carried. Deleting it re-opens a confirmed data exposure.
    -- deposit_amount / deposit_requested_at: the deposit surface reads these.
    'invoices', coalesce((select json_agg(i order by i.created_at desc) from (select id, invoice_number, service_type, amount, amount_paid, status, issued_date, due_date, notes, address, property_id, line_items, job_id, created_at, discount_type, discount_value, deposit_amount, deposit_requested_at from public.invoices where customer_id = v_customer and user_id = v_user and status <> 'draft') i), '[]'::json),
    -- quote_id: which booking a pre-invoice deposit secures. The portal derives
    -- "deposit received" from these rows (signed cash sum), never from a flag.
    'payments', coalesce((select json_agg(pm order by pm.paid_at desc nulls last) from (select id, amount, status, paid_at, provider, kind, invoice_id, quote_id, created_at from public.payments where customer_id = v_customer and user_id = v_user and status = 'paid') pm), '[]'::json),
    -- property_id, quote_id, price, is_initial_visit: buildServicePlans groups by
    -- property and uses jobVisitValue to separate initial from recurring price.
    --
    -- ⛔⛔ THE INTERNAL ACCESS NOTE IS NOT IN THIS PROJECTION, AND MUST NEVER BE
    -- PUT BACK. jobs.notes is written for whoever DOES the work — the job form
    -- calls it "notes for whoever does the work", crew_day ships it to the
    -- worker's phone as "the access note (gate code, where to park)". It was
    -- selected here and rendered verbatim in the customer's visit history: 49 of
    -- 78 completed production visits carried one, including "dog removal, keep
    -- gate closed". Removing it here kills the leak AT THE SOURCE — a portal
    -- component cannot render what was never serialized.
    -- ⛔ jobs.completion_issue is internal for the same reason and likewise absent.
    -- ⭐ jobs.completion_summary is the CUSTOMER-VISIBLE field, written for the
    -- person who paid: it replaces the access note as the words on a finished
    -- visit. `verify:completion` fails the build if either internal field
    -- reappears in this line.
    'jobs', coalesce((select json_agg(j order by j.scheduled_date desc) from (select id, recurrence_id, property_id, quote_id, price, is_initial_visit, service_type, title, scheduled_date, status, on_my_way_at, started_at, completed_at, completion_summary from public.jobs where customer_id = v_customer and user_id = v_user and status <> 'cancelled' order by scheduled_date desc limit 200) j), '[]'::json),
    -- start_date, end_count: the series' own window and count limit.
    'recurrences', coalesce((select json_agg(r) from (select id, freq, interval_unit, interval_count, start_date, end_date, end_count from public.job_recurrences where customer_id = v_customer and user_id = v_user) r), '[]'::json),
    'photos', coalesce((select json_agg(p order by p.taken_at desc) from (select id, job_id, storage_path, kind, caption, taken_at from public.job_photos where customer_id = v_customer and user_id = v_user) p), '[]'::json),
    'change_orders', coalesce((select json_agg(co order by co.created_at desc) from (select id, co_number, job_id, quote_id, description, amount, status, decided_via, created_at, sent_at, approved_at, declined_at from public.change_orders where customer_id = v_customer and user_id = v_user and status <> 'draft') co), '[]'::json),
    'payment_method', (select to_json(pm) from (select brand, last4, exp_month, exp_year from public.payment_methods where customer_id = v_customer and user_id = v_user and is_default order by created_at desc limit 1) pm)
  ) into result;
  return result;
end; $function$;

CREATE OR REPLACE FUNCTION public.guard_business_settings_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- current_app_role() treats "has a business_settings row" as PROOF OF OWNERSHIP,
  -- and RLS lets any authenticated user insert a row for their own uid. So this
  -- INSERT was a one-statement promotion from crew to owner (reproduced: role
  -- flipped 'crew' -> 'owner'), which then unlocked the owner-only invite route.
  -- crew_redeem_invite already refuses the reverse direction ("this account owns
  -- a business — it cannot also join one as crew"); this is the missing mirror.
  if exists (select 1 from public.technicians t where t.auth_user_id = new.user_id) then
    raise exception 'this account is linked to an employee record and cannot own a business'
      using errcode = '42501';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.guard_lawn_sqft_writer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_lawn numeric;
begin
  -- Only relevant when lawn_sqft actually changes (cheap: skips every other update).
  if new.lawn_sqft is not distinct from old.lawn_sqft then return new; end if;
  -- Once the typed ledger has a lawn row, its value is the ONLY legitimate
  -- lawn_sqft — which is exactly what the mirror writes. Anything else is a
  -- legacy direct write trying to diverge from the sensor of record.
  select value into v_lawn from public.property_measurements
    where property_id = new.id and kind = 'lawn';
  if found and new.lawn_sqft is distinct from v_lawn then
    raise exception 'lawn_sqft is derived from property_measurements (kind=lawn); save the measurement through lib/measure, never write lawn_sqft directly'
      using errcode = 'check_violation';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.guard_technician_auth_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- auth_user_id is the employee's IDENTITY LINK. It may only be written by the
  -- flows that prove consent/ownership: crew_redeem_invite + crew_revoke_access
  -- (SECURITY DEFINER, run as postgres) and the owner-authenticated invite route
  -- (service_role). A client-side write would let an "owner" forge a link to a
  -- stranger's auth account and then have the invite route mint a recovery token
  -- for it.
  if current_user in ('postgres', 'service_role', 'supabase_admin') then return new; end if;
  if tg_op = 'INSERT' and new.auth_user_id is not null then
    raise exception 'auth_user_id is set by the invite/join flow, not written directly'
      using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and new.auth_user_id is distinct from old.auth_user_id then
    raise exception 'auth_user_id is set by the invite/join flow, not written directly'
      using errcode = '42501';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.handle_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin new.updated_at = now(); return new; end; $function$;

CREATE OR REPLACE FUNCTION public.inbox_counts()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  with c as (select archived_at, snoozed_until, lead_status, last_channel, last_direction, unread, muted
             from public.conversations where user_id = auth.uid()),
       awake as (select * from c where archived_at is null and (snoozed_until is null or snoozed_until <= now()))
  select jsonb_build_object(
    'all',          (select count(*) from awake),
    'needs_reply',  (select count(*) from awake where last_direction = 'inbound'),
    'sms',          (select count(*) from awake where lead_status is null and (last_channel = 'sms' or last_channel is null)),
    'portal',       (select count(*) from awake where lead_status is null and last_channel = 'portal'),
    'website_lead', (select count(*) from awake where lead_status = 'new'),
    'snoozed',      (select count(*) from c where archived_at is null and snoozed_until > now()),
    'archived',     (select count(*) from c where archived_at is not null),
    'unread_sum',   (select coalesce(sum(unread), 0) from c where archived_at is null and muted = false)
  );
$function$;

CREATE OR REPLACE FUNCTION public.is_verify_fixture_tenant()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select exists (
    select 1 from public.verify_fixture_tenants t where t.user_id = auth.uid()
  );
$function$;

CREATE OR REPLACE FUNCTION public.job_form_default_template(p_job jobs)
 RETURNS TABLE(template_id uuid, source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id uuid;
begin
  if p_job.recurrence_id is not null then
    select r.form_template_id into v_id
    from public.job_recurrences r
    join public.form_templates ft on ft.id = r.form_template_id and ft.user_id = r.user_id
    where r.id = p_job.recurrence_id and r.user_id = p_job.user_id
      and r.form_template_id is not null and ft.archived_at is null;
    if v_id is not null then
      template_id := v_id; source := 'series'; return next; return;
    end if;
  end if;

  if p_job.quote_id is not null then
    select st.form_template_id into v_id
    from public.quotes q
    join public.service_templates st on st.id = q.service_template_id and st.user_id = q.user_id
    join public.form_templates ft on ft.id = st.form_template_id and ft.user_id = st.user_id
    where q.id = p_job.quote_id and q.user_id = p_job.user_id
      and st.form_template_id is not null and ft.archived_at is null;
    if v_id is not null then
      template_id := v_id; source := 'service_template'; return next; return;
    end if;
  end if;

  if p_job.service_type is not null and btrim(p_job.service_type) <> '' then
    select st.form_template_id into v_id
    from public.service_templates st
    join public.form_templates ft on ft.id = st.form_template_id and ft.user_id = st.user_id
    where st.user_id = p_job.user_id
      and lower(btrim(st.name)) = lower(btrim(p_job.service_type))
      and st.form_template_id is not null and ft.archived_at is null
    order by st.sort_order nulls last, st.created_at
    limit 1;
    if v_id is not null then
      template_id := v_id; source := 'service_template'; return next; return;
    end if;
  end if;

  return;
end;
$function$;

CREATE OR REPLACE FUNCTION public.job_form_gate(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_missing jsonb;
begin
  if v_uid is null then return null; end if;
  if not exists (select 1 from public.jobs where id = p_job_id and user_id = v_uid) then
    return null;
  end if;
  v_missing := public.job_form_missing_items(p_job_id, v_uid);
  return jsonb_build_object('ready', jsonb_array_length(v_missing) = 0, 'missing', v_missing);
end;
$function$;

CREATE OR REPLACE FUNCTION public.job_form_missing_items(p_job_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_job public.jobs;
  v_missing jsonb := '[]'::jsonb;
  v_default record;
  v_form record;
  v_field record;
  v_answered boolean;
begin
  select * into v_job from public.jobs where id = p_job_id and user_id = p_user_id;
  if not found then return '[]'::jsonb; end if;

  for v_form in
    select jf.id, jf.template_name, jf.fields, jf.waived_at
    from public.job_forms jf
    where jf.job_id = v_job.id and jf.user_id = v_job.user_id
  loop
    if v_form.waived_at is not null then continue; end if;
    for v_field in
      select (f ->> 'id')::uuid as id, f ->> 'label' as label, f ->> 'type' as type
      from jsonb_array_elements(v_form.fields) f
      where (f ->> 'required')::boolean is true
        and f ->> 'type' not in ('section','instruction')
    loop
      if v_field.type = 'photo' then
        select exists (
          select 1 from public.job_form_responses r
          join public.job_form_response_photos p on p.response_id = r.id and p.user_id = r.user_id
          where r.form_id = v_form.id and r.user_id = v_job.user_id and r.field_id = v_field.id
        ) into v_answered;
      else
        select exists (
          select 1 from public.job_form_responses r
          where r.form_id = v_form.id and r.user_id = v_job.user_id and r.field_id = v_field.id
        ) into v_answered;
      end if;
      if not v_answered then
        v_missing := v_missing || jsonb_build_object(
          'form_id', v_form.id, 'form', v_form.template_name,
          'field_id', v_field.id, 'label', v_field.label, 'type', v_field.type);
      end if;
    end loop;
  end loop;

  -- A default that never got opened still gates: count its required fields
  -- from the LIVE template (nothing was snapshotted yet, so the live
  -- definition is exactly what would have attached).
  select * into v_default from public.job_form_default_template(v_job);
  if v_default.template_id is not null and not exists (
    select 1 from public.job_forms jf
    where jf.job_id = v_job.id and jf.user_id = v_job.user_id and jf.template_id = v_default.template_id
  ) then
    for v_field in
      select f.id, f.label, f.field_type as type, ft.name as form_name
      from public.form_template_fields f
      join public.form_templates ft on ft.id = f.template_id and ft.user_id = f.user_id
      where f.template_id = v_default.template_id and f.user_id = v_job.user_id
        and f.required and f.field_type not in ('section','instruction')
    loop
      v_missing := v_missing || jsonb_build_object(
        'form_id', null, 'form', v_field.form_name,
        'field_id', v_field.id, 'label', v_field.label, 'type', v_field.type);
    end loop;
  end if;

  return v_missing;
end;
$function$;

CREATE OR REPLACE FUNCTION public.job_form_response_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.job_form_responses;
  v_form public.job_forms;
  v_job public.jobs;
  v_field jsonb;
  v_type text;
  v_values int;
begin
  if tg_op = 'DELETE' then v_row := old; else v_row := new; end if;
  select * into v_form from public.job_forms where id = v_row.form_id and user_id = v_row.user_id;
  if not found then
    raise exception 'response does not belong to a form of this business';
  end if;
  select * into v_job from public.jobs where id = v_form.job_id;

  -- ?? the freeze ?????????????????????????????????????????????????????????????
  if v_job.status = 'completed' then
    if tg_op = 'DELETE' then
      raise exception 'this visit is completed - its checklist is a historical record and answers cannot be removed';
    end if;
    if new.correction_reason is null or new.corrected_at is null or new.corrected_by is null then
      raise exception 'this visit is completed - a change to its checklist must be an explicit correction with a reason';
    end if;
    if auth.uid() is not null and new.corrected_by is distinct from auth.uid() then
      raise exception 'a correction must name the person who made it';
    end if;
    if new.answered_role = 'crew' and tg_op = 'UPDATE' then
      raise exception 'a completed checklist is frozen for crew - ask the office to correct it';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;

  -- ?? attribution is real ???????????????????????????????????????????????????
  -- A new answer names the session that wrote it. A re-answer moves the
  -- attribution to the re-answerer. The ONE exception: an owner CORRECTION may
  -- keep the original answered_by (history says who answered; corrected_by
  -- says who amended it) - but then corrected_by must be the session.
  if auth.uid() is not null and new.answered_by is distinct from auth.uid() then
    if not (tg_op = 'UPDATE'
            and new.answered_by = old.answered_by
            and new.corrected_by = auth.uid()) then
      raise exception 'an answer must be attributed to the session that wrote it';
    end if;
  end if;

  -- ?? the field must exist in the snapshot, and be answerable ???????????????
  select f into v_field
  from jsonb_array_elements(v_form.fields) f
  where (f ->> 'id')::uuid = new.field_id;
  if v_field is null then
    raise exception 'that field is not on this form';
  end if;
  v_type := v_field ->> 'type';
  if v_type in ('section','instruction') then
    raise exception 'headings and instructions are not answerable';
  end if;

  -- ?? exactly the right value, never an empty one ???????????????????????????
  v_values := (new.value_text is not null)::int + (new.value_number is not null)::int
            + (new.value_bool is not null)::int + (new.value_date is not null)::int
            + (new.value_time is not null)::int + (new.value_choice is not null)::int;

  if v_type = 'photo' then
    if v_values <> 0 then
      raise exception 'a photo field carries photos, not a typed value';
    end if;
  elsif v_values <> 1 then
    raise exception 'a response carries exactly one value (got %)', v_values;
  elsif v_type = 'checkbox' then
    if new.value_bool is not true then
      raise exception 'a checkbox is either checked (true) or has no response row at all';
    end if;
  elsif v_type = 'yes_no' then
    if new.value_bool is null then
      raise exception 'a yes/no answer is the value_bool column';
    end if;
  elsif v_type in ('short_text','long_text') then
    if new.value_text is null or btrim(new.value_text) = '' then
      raise exception 'a text answer cannot be blank';
    end if;
    if v_type = 'short_text' and char_length(new.value_text) > 200 then
      raise exception 'a short answer is at most 200 characters';
    end if;
  elsif v_type = 'number' then
    if new.value_number is null then
      raise exception 'a number answer is the value_number column';
    end if;
  elsif v_type = 'dropdown' then
    if new.value_choice is null then
      raise exception 'a dropdown answer is the value_choice column';
    end if;
    if not exists (
      select 1 from jsonb_array_elements(coalesce(v_field -> 'options', '[]'::jsonb)) o
      where o #>> '{}' = new.value_choice
    ) then
      raise exception 'that choice is not one of this field''s options';
    end if;
  elsif v_type = 'date' then
    if new.value_date is null then
      raise exception 'a date answer is the value_date column';
    end if;
  elsif v_type = 'time' then
    if new.value_time is null then
      raise exception 'a time answer is the value_time column';
    end if;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.job_form_response_photo_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_resp public.job_form_responses;
  v_form public.job_forms;
  v_job public.jobs;
  v_photo public.job_photos;
  v_field jsonb;
begin
  select * into v_resp from public.job_form_responses where id = new.response_id and user_id = new.user_id;
  if not found then raise exception 'that response does not exist in this business'; end if;
  select * into v_form from public.job_forms where id = v_resp.form_id and user_id = v_resp.user_id;
  select * into v_job from public.jobs where id = v_form.job_id;
  select * into v_photo from public.job_photos where id = new.photo_id and user_id = new.user_id;
  if not found then raise exception 'that photo does not exist in this business'; end if;

  if v_photo.job_id is distinct from v_form.job_id then
    raise exception 'a checklist photo must be a photo of this visit, not another one';
  end if;
  select f into v_field
  from jsonb_array_elements(v_form.fields) f
  where (f ->> 'id')::uuid = v_resp.field_id;
  if v_field is null or (v_field ->> 'type') <> 'photo' then
    raise exception 'photos attach to photo fields only';
  end if;
  if v_job.status = 'completed' then
    raise exception 'this visit is completed - its checklist evidence is a historical record';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.job_form_summary(p_job_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_job public.jobs;
  v_total int := 0;
  v_done int := 0;
  v_req_total int := 0;
  v_req_done int := 0;
  v_forms int := 0;
  v_waived boolean := false;
  v_default record;
  v_form record;
  v_field record;
  v_answered boolean;
begin
  select * into v_job from public.jobs where id = p_job_id and user_id = p_user_id;
  if not found then return null; end if;

  for v_form in
    select jf.id, jf.fields, jf.waived_at
    from public.job_forms jf
    where jf.job_id = v_job.id and jf.user_id = v_job.user_id
  loop
    v_forms := v_forms + 1;
    if v_form.waived_at is not null then v_waived := true; end if;
    for v_field in
      select (f ->> 'id')::uuid as id, f ->> 'type' as type,
             coalesce((f ->> 'required')::boolean, false) as required
      from jsonb_array_elements(v_form.fields) f
      where f ->> 'type' not in ('section','instruction')
    loop
      if v_field.type = 'photo' then
        select exists (
          select 1 from public.job_form_responses r
          join public.job_form_response_photos p on p.response_id = r.id and p.user_id = r.user_id
          where r.form_id = v_form.id and r.user_id = v_job.user_id and r.field_id = v_field.id
        ) into v_answered;
      else
        select exists (
          select 1 from public.job_form_responses r
          where r.form_id = v_form.id and r.user_id = v_job.user_id and r.field_id = v_field.id
        ) into v_answered;
      end if;
      v_total := v_total + 1;
      if v_answered then v_done := v_done + 1; end if;
      if v_field.required then
        v_req_total := v_req_total + 1;
        if v_answered then v_req_done := v_req_done + 1; end if;
      end if;
    end loop;
  end loop;

  select * into v_default from public.job_form_default_template(v_job);
  if v_default.template_id is not null and not exists (
    select 1 from public.job_forms jf
    where jf.job_id = v_job.id and jf.user_id = v_job.user_id and jf.template_id = v_default.template_id
  ) then
    v_forms := v_forms + 1;
    select v_total + count(*),
           v_req_total + count(*) filter (where f.required)
      into v_total, v_req_total
    from public.form_template_fields f
    where f.template_id = v_default.template_id and f.user_id = v_job.user_id
      and f.field_type not in ('section','instruction');
  end if;

  if v_forms = 0 then return null; end if;
  return jsonb_build_object(
    'forms', v_forms, 'items', v_total, 'done', v_done,
    'required', v_req_total, 'required_done', v_req_done,
    'waived', v_waived);
end;
$function$;

CREATE OR REPLACE FUNCTION public.job_forms_completion_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_missing jsonb;
  v_labels text;
begin
  if new.status = 'completed' and old.status is distinct from 'completed' then
    v_missing := public.job_form_missing_items(new.id, new.user_id);
    if jsonb_array_length(v_missing) > 0 then
      select string_agg(m ->> 'label', ' � ') into v_labels
      from (select m from jsonb_array_elements(v_missing) m limit 4) s;
      raise exception 'CHECKLIST_INCOMPLETE Before completing: %', v_labels
        using hint = 'Finish the required checklist items, or waive the checklist with a reason.';
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.job_forms_freeze_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.fields is distinct from old.fields
     or new.template_name is distinct from old.template_name
     or new.template_id is distinct from old.template_id
     or new.job_id is distinct from old.job_id
     or new.user_id is distinct from old.user_id
     or new.source is distinct from old.source
     or new.created_at is distinct from old.created_at then
    raise exception 'a job form is a historical record - its snapshot cannot be edited (only waive fields may change)';
  end if;
  -- a waive is an override with a name on it: the waiver must be the session
  if new.waived_at is not null and old.waived_at is null then
    if auth.uid() is not null and new.waived_by is distinct from auth.uid() then
      raise exception 'a waive must name the person who waived it';
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.job_session_minutes(p_job_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select sum(minutes)::integer from public.job_work_sessions where job_id = p_job_id;
$function$;

CREATE OR REPLACE FUNCTION public.jobs_assignment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.crew_id is not null
     and (tg_op = 'INSERT' or new.crew_id is distinct from old.crew_id)
     and exists (select 1 from public.crews c where c.id = new.crew_id and not c.is_active) then
    raise exception 'that crew is deactivated — reactivate it or choose another'
      using errcode = '23514';
  end if;
  if new.technician_id is not null
     and (tg_op = 'INSERT' or new.technician_id is distinct from old.technician_id)
     and exists (
       select 1 from public.technicians t
       where t.id = new.technician_id and (not t.is_active or t.archived_at is not null)
     ) then
    raise exception 'that person is not on the active roster'
      using errcode = '23514';
  end if;
  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.list_beta_invites()
 RETURNS TABLE(id uuid, label text, email text, created_at timestamp with time zone, expires_at timestamp with time zone, state text, reserved_at timestamp with time zone, redeemed_at timestamp with time zone, send_count integer, last_sent_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.uid() is null
     or not exists (select 1 from public.platform_operators o where o.user_id = auth.uid()) then
    raise exception 'only a platform operator can list beta invites' using errcode = '42501';
  end if;
  return query
  select i.id, i.label, i.email, i.created_at, i.expires_at,
         case
           when i.revoked_at  is not null then 'revoked'
           when i.redeemed_at is not null then 'redeemed'
           when i.reserved_by is not null then 'reserved'
           when i.expires_at < now()      then 'expired'
           else 'open'
         end,
         i.reserved_at, i.redeemed_at, i.send_count, i.last_sent_at
    from public.beta_invites i
   order by i.created_at desc;
end
$function$;

CREATE OR REPLACE FUNCTION public.log_measurement_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    insert into public.property_measurement_events
      (user_id, property_id, measurement_id, kind, unit, value, shapes, source, confidence, confidence_reason, action, measured_at)
    values (old.user_id, old.property_id, old.id, old.kind, old.unit, old.value, old.shapes,
            old.source, old.confidence, old.confidence_reason, 'removed', old.measured_at);
    return null;
  end if;
  -- Only log when something a reader would care about actually moved. An
  -- unchanged re-save is not a measurement event.
  if tg_op = 'UPDATE'
     and new.value is not distinct from old.value
     and new.source is not distinct from old.source
     and new.shapes is not distinct from old.shapes then
    return null;
  end if;
  insert into public.property_measurement_events
    (user_id, property_id, measurement_id, kind, unit, value, shapes, source, confidence, confidence_reason, action, measured_at)
  values (new.user_id, new.property_id, new.id, new.kind, new.unit, new.value, new.shapes,
          new.source, new.confidence, new.confidence_reason, 'measured', new.measured_at);
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.log_wage_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.hourly_wage is not null then
      insert into public.wage_history (user_id, technician_id, old_wage, new_wage, note)
      values (new.user_id, new.id, null, new.hourly_wage, 'Starting wage');
    end if;
    return new;
  end if;
  if new.hourly_wage is distinct from old.hourly_wage then
    insert into public.wage_history (user_id, technician_id, old_wage, new_wage)
    values (new.user_id, new.id, old.hourly_wage, new.hourly_wage);
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.mirror_measurement_to_property()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare target uuid; v numeric;
begin
  target := coalesce(new.property_id, old.property_id);
  v := case when tg_op = 'DELETE' then null else new.value end;

  case coalesce(new.kind, old.kind)
    when 'lawn'    then update public.properties set lawn_sqft    = v where id = target;
    when 'fencing' then update public.properties set fence_length = v where id = target;
    when 'mulch'   then update public.properties set mulch_area   = v where id = target;
    when 'rock'    then update public.properties set rock_area    = v where id = target;
    else null;
  end case;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.notify_change_order_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text;
begin
  if new.status not in ('approved', 'declined') or old.status is not distinct from new.status then
    return null;
  end if;
  if new.decided_via is distinct from 'portal' then return null; end if;
  select name into v_name from public.customers where id = new.customer_id;
  insert into public.notifications (user_id, type, title, body, customer_id, entity_type, entity_id, amount, href)
  values (
    new.user_id,
    case when new.status = 'approved' then 'change_order_approved' else 'change_order_declined' end,
    coalesce(nullif(v_name, ''), 'A customer') ||
      case when new.status = 'approved' then ' approved a change' else ' declined a change' end,
    new.co_number || ' - $' || trim(to_char(new.amount, 'FM999990D00')) || ' - ' || left(new.description, 80),
    new.customer_id, 'job', new.job_id, new.amount, '/dashboard/schedule?focus=' || new.job_id
  );
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.notify_inbound_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text; v_muted boolean;
begin
  if new.direction <> 'inbound' then return new; end if;
  select muted into v_muted from public.conversations where id = new.conversation_id;
  if coalesce(v_muted, false) then return new; end if;
  select name into v_name from public.customers where id = new.customer_id;
  insert into public.notifications (user_id, type, title, body, customer_id, entity_type, entity_id, href)
  values (
    new.user_id,
    case when new.channel = 'portal' and (new.meta ? 'service_request_id') then 'portal_request'
         else 'new_message' end,
    coalesce(nullif(v_name, ''), 'A customer')
      || case when new.channel = 'portal' and (new.meta ? 'service_request_id') then ' sent a request from the portal'
              when new.channel = 'portal' then ' sent you a message from the portal'
              else ' replied by text' end,
    left(new.body, 140),
    new.customer_id, 'message', new.id, '/dashboard/messages?c=' || new.customer_id
  );
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.notify_invoice_paid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'paid' and old.status is distinct from 'paid' then
    insert into public.notifications (user_id, type, title, body, customer_id, entity_type, entity_id, amount, href)
    values (new.user_id, 'invoice_paid',
      coalesce(nullif(new.customer_name,''), 'A customer') || ' paid an invoice',
      'Invoice ' || coalesce(new.invoice_number, '') || ' · $' || trim(to_char(coalesce(new.amount,0), 'FM999990D00')) || ' received',
      new.customer_id, 'invoice', new.id, new.amount, '/dashboard/invoices');
  end if;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.notify_quote_accepted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'accepted' and old.status is distinct from 'accepted' then
